    conditional_identifier: ConditionalIdentifierType | None = Field(default=None, alias="ConditionalIdentifier", description="Describes the information needed to identify a specific record or case within a record type. Repeating the field allows multiple means of identifying a case referencing multiple variables.", json_schema_extra={"cogs_name": "ConditionalIdentifier", "description": "Describes the information needed to identify a specific record or case within a record type. Repeating the field allows multiple means of identifying a case referencing multiple variables.", "type_name": "ConditionalIdentifierType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
