    location_in_archive: list[LangString] = Field(default_factory=list, alias="LocationInArchive", description="Describes the location of the collection within the archive.", json_schema_extra={"cogs_name": "LocationInArchive", "description": "Describes the location of the collection within the archive.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    call_number: str | None = Field(default=None, alias="CallNumber", description="The name, code, or number used by the archive to uniquely identify the collection within the archive.", json_schema_extra={"cogs_name": "CallNumber", "description": "The name, code, or number used by the archive to uniquely identify the collection within the archive.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    uri: str | None = Field(default=None, alias="URI", description="The URL or URN for the collection.", json_schema_extra={"cogs_name": "URI", "description": "The URL or URN for the collection.", "type_name": "anyURI", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    item_quantity: int | None = Field(default=None, alias="ItemQuantity", description="The number of items in the collection. This is a check sum and should be updated as the contents of the collection changes. The use of this element is best restricted to completed collections where change in the number of objects is not dynamic.", json_schema_extra={"cogs_name": "ItemQuantity", "description": "The number of items in the collection. This is a check sum and should be updated as the contents of the collection changes. The use of this element is best restricted to completed collections where change in the number of objects is not dynamic.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    study_class: StudyClassType | None = Field(default=None, alias="StudyClass", description="An archive specific classification for the collection. This may be a topical classification, a classification of intended processing levels, or information on the processing status.", json_schema_extra={"cogs_name": "StudyClass", "description": "An archive specific classification for the collection. This may be a topical classification, a classification of intended processing levels, or information on the processing status.", "type_name": "StudyClassType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    default_access: AccessType | None = Field(default=None, alias="DefaultAccess", description="Default access restriction information applying to all of the items in the collection.", json_schema_extra={"cogs_name": "DefaultAccess", "description": "Default access restriction information applying to all of the items in the collection.", "type_name": "AccessType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
