    agency: str | None = Field(default=None, alias="Agency", description="This is the registered agency code with optional sub-agencies separated by dots.", json_schema_extra={"cogs_name": "Agency", "description": "This is the registered agency code with optional sub-agencies separated by dots.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
