    version: str | None = Field(default=None, alias="Version", description="The version number of the object. For the identifiable object this is the version number of its parent versionable at the point of creation or alteration of the non-administrative metadata of the identifiable. Versionable and Maintainable items increment their version number whenever the non-administrative metadata contained by the object changes.", json_schema_extra={"cogs_name": "Version", "description": "The version number of the object. For the identifiable object this is the version number of its parent versionable at the point of creation or alteration of the non-administrative metadata of the identifiable. Versionable and Maintainable items increment their version number whenever the non-administrative metadata contained by the object changes.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
