    controlled_vocabulary_id: str | None = Field(default=None, alias="ControlledVocabularyID", description="The ID of the code controlled vocabulary that the content was taken from.", json_schema_extra={"cogs_name": "ControlledVocabularyID", "description": "The ID of the code controlled vocabulary that the content was taken from.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
