    controlled_vocabulary_agency_name: str | None = Field(default=None, alias="ControlledVocabularyAgencyName", description="The name of the agency maintaining the controlledVocabulary.", json_schema_extra={"cogs_name": "ControlledVocabularyAgencyName", "description": "The name of the agency maintaining the controlledVocabulary.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    controlled_vocabulary_version_id: str | None = Field(default=None, alias="ControlledVocabularyVersionID", description="The version number of the controlledVocabulary.", json_schema_extra={"cogs_name": "ControlledVocabularyVersionID", "description": "The version number of the controlledVocabulary.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
