    item_format: CodeValueType | None = Field(default=None, alias="ItemFormat", description="Describes the item's format.", json_schema_extra={"cogs_name": "ItemFormat", "description": "Describes the item's format.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    media: CodeValueType | None = Field(default=None, alias="Media", description="Describes the medium, or media, for the item.", json_schema_extra={"cogs_name": "Media", "description": "Describes the medium, or media, for the item.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
