    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the code Level.", json_schema_extra={"cogs_name": "Description", "description": "A description of the code Level.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    category_relationship: str | None = Field(default=None, alias="CategoryRelationship", description="Describes the relationships among categories at that respective level. Possible values are either Nominal, Ordinal, or Interval. Note that different levels may have different types of relationships within the same hierarchy. For example, Level 1 items may be ordinal and Level 2 (the children of Level 1 items) may be nominal.", json_schema_extra={"cogs_name": "CategoryRelationship", "description": "Describes the relationships among categories at that respective level. Possible values are either Nominal, Ordinal, or Interval. Note that different levels may have different types of relationships within the same hierarchy. For example, Level 1 items may be ordinal and Level 2 (the children of Level 1 items) may be nominal.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    interval_increment: BasicIncrementType | None = Field(default=None, alias="IntervalIncrement", description="Identifies the interval between each value of the codes at this level. Used only for codes with interval relationship.", json_schema_extra={"cogs_name": "IntervalIncrement", "description": "Identifies the interval between each value of the codes at this level. Used only for codes with interval relationship.", "type_name": "BasicIncrementType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
