    array_order: int | None = Field(default=None, alias="ArrayOrder", description="Oder within the array. Note that this attribute assumes an array base of 0. The array order assumes that the measures will always be displayed in the same order and that sparse content (a missing value in the array) will be clear between two delimiters in this array. (For example 1,1,1 or 1,,1)", json_schema_extra={"cogs_name": "ArrayOrder", "description": "Oder within the array. Note that this attribute assumes an array base of 0. The array order assumes that the measures will always be displayed in the same order and that sparse content (a missing value in the array) will be clear between two delimiters in this array. (For example 1,1,1 or 1,,1)", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

