class NoteType(CogsValue):
    "A note related to one or more identifiable objects. Note is designed to be an inherent part of the DDI. (Unlike XML comments or other types of system-level annotations, which may be removed during processing.) DDI recommends placing the note within the maintainable object containing the objects this note relates to in order to assist tracking of note items within a study. Each note may indicate who is responsible for the note, its type using a controlled vocabulary, the subject of the note, a head and note content, a set of key/value pairs and language specification for the overall note. In addition each note must be related to one or more identifiable objects."
    _cogs_type: ClassVar[str] = "NoteType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = False
    type_of_note: CodeValueType | None = Field(default=None, alias="TypeOfNote", description="Specifies the type of note. Supports the use of a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (TypeOfNote) to support this element at http://www.ddialliance.org/controlled-vocabularies.", json_schema_extra={"cogs_name": "TypeOfNote", "description": "Specifies the type of note. Supports the use of a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (TypeOfNote) to support this element at http://www.ddialliance.org/controlled-vocabularies.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    note_subject: CodeValueType | None = Field(default=None, alias="NoteSubject", description="The subject of the note.", json_schema_extra={"cogs_name": "NoteSubject", "description": "The subject of the note.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    relationship: list[RelationshipType] = Field(default_factory=list, alias="Relationship", description="Reference to one or more identifiable objects which the note is related to.", json_schema_extra={"cogs_name": "Relationship", "description": "Reference to one or more identifiable objects which the note is related to.", "type_name": "RelationshipType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    responsibility: str | None = Field(default=None, alias="Responsibility", description="The person or agency responsible for adding the note.", json_schema_extra={"cogs_name": "Responsibility", "description": "The person or agency responsible for adding the note.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    header: list[LangString] = Field(default_factory=list, alias="Header", description="A brief label or heading for the note contents.", json_schema_extra={"cogs_name": "Header", "description": "A brief label or heading for the note contents.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    note_content: list[LangString] = Field(default_factory=list, alias="NoteContent", description="The content of the note. Note should contain content except when it is a production flag that is fully explained by its \"type\". If the note provides system specific information in a structured way using XHTML formating, DDI strongly recommends the use of local extensions or the Key/Value pair structure in ProprietaryInfo whenever possible.", json_schema_extra={"cogs_name": "NoteContent", "description": "The content of the note. Note should contain content except when it is a production flag that is fully explained by its \"type\". If the note provides system specific information in a structured way using XHTML formating, DDI strongly recommends the use of local extensions or the Key/Value pair structure in ProprietaryInfo whenever possible.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    proprietary_info: ProprietaryInfoType | None = Field(default=None, alias="ProprietaryInfo", description="A set of actions related to the object as described by a set of name-value pairs. This would commonly be used in a case where additional information needs to be recorded regarding the content of a new element or attribute that has not yet been added to the schema, for example when a bug for a missing object has been filed and the user wishes to record the content prior to correction in the schema. Ideally this should be handled by local extensions of the schema as described in Part 2 of the formal documentation. However, the structure in Note allows for an unanticipated need for an extension at run time by providing a means of capturing system specific information in a structured way.", json_schema_extra={"cogs_name": "ProprietaryInfo", "description": "A set of actions related to the object as described by a set of name-value pairs. This would commonly be used in a case where additional information needs to be recorded regarding the content of a new element or attribute that has not yet been added to the schema, for example when a bug for a missing object has been filed and the user wishes to record the content prior to correction in the schema. Ideally this should be handled by local extensions of the schema as described in Part 2 of the formal documentation. However, the structure in Note allows for an unanticipated need for an extension at run time by providing a means of capturing system specific information in a structured way.", "type_name": "ProprietaryInfoType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    lang: str | None = Field(default=None, alias="Lang", description="Indicates the language of content. Note that xml:lang allows for a simple 2 or 3 character language code or a language code extended by a country code , for example en-au for English as used in Australia.", json_schema_extra={"cogs_name": "Lang", "description": "Indicates the language of content. Note that xml:lang allows for a simple 2 or 3 character language code or a language code extended by a country code , for example en-au for English as used in Australia.", "type_name": "language", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

