    weight_variable_reference: list[Variable] = Field(default_factory=list, alias="WeightVariableReference", description="Reference to one or more weight variables that may be used in analyzing this variable.", json_schema_extra={"cogs_name": "WeightVariableReference", "description": "Reference to one or more weight variables that may be used in analyzing this variable.", "type_name": "Variable", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    standard_weight_reference: StandardWeightType | None = Field(default=None, alias="StandardWeightReference", description="Reference to the StandardWeight found in the Weighting description, which is relevant for analyzing this variable. A standard weight is a single weight used for all variables of a specific type or for a specified sub-universe.", json_schema_extra={"cogs_name": "StandardWeightReference", "description": "Reference to the StandardWeight found in the Weighting description, which is relevant for analyzing this variable. A standard weight is a single weight used for all variables of a specific type or for a specified sub-universe.", "type_name": "StandardWeightType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    variable_attribute: list[VariableAttributeType] = Field(default_factory=list, alias="VariableAttribute", description="An attribute may be any object which should be attached to or coupled with a Variable such as a related suppression flag, source flag, footnote, etc. It may be defined as a Variable or contain textual content (such as a footnote).", json_schema_extra={"cogs_name": "VariableAttribute", "description": "An attribute may be any object which should be attached to or coupled with a Variable such as a related suppression flag, source flag, footnote, etc. It may be defined as a Variable or contain textual content (such as a footnote).", "type_name": "VariableAttributeType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    imputation_reference: SerializeAsAny[ProcessingInstruction] | None = Field(default=None, alias="ImputationReference", description="Reference to the imputation process described as a General Instruction in a ProcessingInstructionScheme.", json_schema_extra={"cogs_name": "ImputationReference", "description": "Reference to the imputation process described as a General Instruction in a ProcessingInstructionScheme.", "type_name": "ProcessingInstruction", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    concatenated_value: ConcatenatedValueType | None = Field(default=None, alias="ConcatenatedValue", description="Provides a reference to other variables and describes the method for deriving the value of this variable by concatenating a collection of other variables. This is useful in creating concatenated keys.", json_schema_extra={"cogs_name": "ConcatenatedValue", "description": "Provides a reference to other variables and describes the method for deriving the value of this variable by concatenating a collection of other variables. This is useful in creating concatenated keys.", "type_name": "ConcatenatedValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    processing_instruction_reference: SerializeAsAny[ProcessingInstruction] | None = Field(default=None, alias="ProcessingInstructionReference", description="A reference to either a general or generation instruction that was provided to those who converted information from one form to another to create a particular variable. This might include the reordering of numeric information into another form or the conversion of textual information into numeric information. TypeOfObject should be set to GeneralInstruction or GenerationInstruction.", json_schema_extra={"cogs_name": "ProcessingInstructionReference", "description": "A reference to either a general or generation instruction that was provided to those who converted information from one form to another to create a particular variable. This might include the reordering of numeric information into another form or the conversion of textual information into numeric information. TypeOfObject should be set to GeneralInstruction or GenerationInstruction.", "type_name": "ProcessingInstruction", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    value_representation: SerializeAsAny[RepresentationType] | None = Field(default=None, alias="ValueRepresentation", description="Describes the actual representation of the variables' values. Allows for the listing of values to be treated as missing in order to support 3.1 structures. The preferred method is the use of a reference to ManagedMissingValues description using MissingValuesReference. If both are used and there is a conflict in the content, MissingValuesReference will override the content provided in the ValueRepresentationReference.", json_schema_extra={"cogs_name": "ValueRepresentation", "description": "Describes the actual representation of the variables' values. Allows for the listing of values to be treated as missing in order to support 3.1 structures. The preferred method is the use of a reference to ManagedMissingValues description using MissingValuesReference. If both are used and there is a conflict in the content, MissingValuesReference will override the content provided in the ValueRepresentationReference.", "type_name": "RepresentationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": True})
    value_representation_reference: SerializeAsAny[ManagedRepresentation] | None = Field(default=None, alias="ValueRepresentationReference", description="Allows for the use of a ManagedRepresentation by reference. ValueRepresentationReference is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentationReference.", json_schema_extra={"cogs_name": "ValueRepresentationReference", "description": "Allows for the use of a ManagedRepresentation by reference. ValueRepresentationReference is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentationReference.", "type_name": "ManagedRepresentation", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    missing_values_reference: ManagedMissingValuesRepresentation | None = Field(default=None, alias="MissingValuesReference", description="Reference to an existing MissingValuesRepresentation using the Reference structure. If this content conflicts with content provided in the ValueRepresentation regarding Missing Values the content of the MissingValuesRepresentation overrides. TypeOfObject will be MissingValuesRepresentation", json_schema_extra={"cogs_name": "MissingValuesReference", "description": "Reference to an existing MissingValuesRepresentation using the Reference structure. If this content conflicts with content provided in the ValueRepresentation regarding Missing Values the content of the MissingValuesRepresentation overrides. TypeOfObject will be MissingValuesRepresentation", "type_name": "ManagedMissingValuesRepresentation", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    content_date_offset: ContentDateOffsetType | None = Field(default=None, alias="ContentDateOffset", description="Identifies the difference between the date applied to the data as a whole and this specific item such as previous year's income or residence 5 years ago.", json_schema_extra={"cogs_name": "ContentDateOffset", "description": "Identifies the difference between the date applied to the data as a whole and this specific item such as previous year's income or residence 5 years ago.", "type_name": "ContentDateOffsetType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    aggregation_method: CodeValueType | None = Field(default=None, alias="AggregationMethod", description="Indicates the type of aggregation method used. Supports the use of a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (AggregationMethod) to support this element at http://www.ddialliance.org/controlled-vocabularies.", json_schema_extra={"cogs_name": "AggregationMethod", "description": "Indicates the type of aggregation method used. Supports the use of a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (AggregationMethod) to support this element at http://www.ddialliance.org/controlled-vocabularies.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    additivity: str | None = Field(default=None, alias="Additivity", description="Records type of additivity, such as 'stock', 'flow', 'non-additive'.", json_schema_extra={"cogs_name": "Additivity", "description": "Records type of additivity, such as 'stock', 'flow', 'non-additive'.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

