    agency: str | None = Field(default=None, alias="Agency", description="", json_schema_extra={"cogs_name": "Agency", "description": "", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    id: str | None = Field(default=None, alias="ID", description="", json_schema_extra={"cogs_name": "ID", "description": "", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
