    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the category. Note that comparison of categories is done using the content of description.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the category. Note that comparison of categories is done using the content of description.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    concept_reference: Concept | None = Field(default=None, alias="ConceptReference", description="Reference to the defining concept.", json_schema_extra={"cogs_name": "ConceptReference", "description": "Reference to the defining concept.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    generation: GenerationType | None = Field(default=None, alias="Generation", description="Describes how the category is derived or generated. A process for describing the determination of category membership.", json_schema_extra={"cogs_name": "Generation", "description": "Describes how the category is derived or generated. A process for describing the determination of category membership.", "type_name": "GenerationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    sub_category_reference: list[Category] = Field(default_factory=list, alias="SubCategoryReference", description="Reference to one or more categories for which the current category is a broader definition. Allows for a reference to the narrower category and the ability to define the relationship as a specialization or part.", json_schema_extra={"cogs_name": "SubCategoryReference", "description": "Reference to one or more categories for which the current category is a broader definition. Allows for a reference to the narrower category and the ability to define the relationship as a specialization or part.", "type_name": "Category", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    is_missing: bool | None = Field(default=None, alias="IsMissing", description="If the category is describing a classification of \"missing data\" set the value of isMissing to \"true\".", json_schema_extra={"cogs_name": "IsMissing", "description": "If the category is describing a classification of \"missing data\" set the value of isMissing to \"true\".", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

