class CodeType(IdentifiableType):
    "A structure that links a unique value of a code to a specified category and provides information as to the location of the code within a hierarchy, whether it is discrete, represents a total for the CodeList contents, and if its sub-elements represent a comprehensive coverage of the code. The Code is identifiable, but the value within the code must also be unique within the CodeList."
    _cogs_type: ClassVar[str] = "CodeType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    category_reference: Category | None = Field(default=None, alias="CategoryReference", description="Reference to the category that the code value represents.", json_schema_extra={"cogs_name": "CategoryReference", "description": "Reference to the category that the code value represents.", "type_name": "Category", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    value: ValueType | None = Field(default=None, alias="Value", description="The value of the code. In a microdata file this would be the value found in the data file. If used as the description of an NCube dimension the value provides the coordinate value for that dimension. Note that r:Value has an attribute xml:space with the default value of \"default\". If white space is critical to the understanding of this code value (such as critical leading or tailing spaces, or multiple spaces within the code) change the value of xml:space to \"preserve\".", json_schema_extra={"cogs_name": "Value", "description": "The value of the code. In a microdata file this would be the value found in the data file. If used as the description of an NCube dimension the value provides the coordinate value for that dimension. Note that r:Value has an attribute xml:space with the default value of \"default\". If white space is critical to the understanding of this code value (such as critical leading or tailing spaces, or multiple spaces within the code) change the value of xml:space to \"preserve\".", "type_name": "ValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    code: list[CodeType] = Field(default_factory=list, alias="Code", description="Allows for nesting of codes.", json_schema_extra={"cogs_name": "Code", "description": "Allows for nesting of codes.", "type_name": "CodeType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    is_discrete: bool | None = Field(default=None, alias="IsDiscrete", description="Indicates whether the code is discrete (that is, placed at the lowest level in a hierarchy and has no children).", json_schema_extra={"cogs_name": "IsDiscrete", "description": "Indicates whether the code is discrete (that is, placed at the lowest level in a hierarchy and has no children).", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    level_number: int | None = Field(default=None, alias="LevelNumber", description="Level number of the code.", json_schema_extra={"cogs_name": "LevelNumber", "description": "Level number of the code.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    is_comprehensive: str | None = Field(default=None, alias="IsComprehensive", description="Used in hierarchical structures at upper level values to indicate whether or not the subelements of the code are comprehensive in coverage. Not applicable if attribute isDiscrete is set to \"true\".", json_schema_extra={"cogs_name": "IsComprehensive", "description": "Used in hierarchical structures at upper level values to indicate whether or not the subelements of the code are comprehensive in coverage. Not applicable if attribute isDiscrete is set to \"true\".", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    is_total: bool | None = Field(default=None, alias="IsTotal", description="This expresses a total whether or not isComprehensive is true. If isComprehensive = \"true\" then if addition is supported by the measure type, the contained categories can be aggregated to calculate the total. If isComprehensive = \"false\" or \"unknown\" the content of this field cannot be calculated if the value is not provided in the data.", json_schema_extra={"cogs_name": "IsTotal", "description": "This expresses a total whether or not isComprehensive is true. If isComprehensive = \"true\" then if addition is supported by the measure type, the contained categories can be aggregated to calculate the total. If isComprehensive = \"false\" or \"unknown\" the content of this field cannot be calculated if the value is not provided in the data.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

