    data_collection_frequency: list[DataCollectionFrequencyType] = Field(default_factory=list, alias="DataCollectionFrequency", description="Documents the intended frequency of data collection, for example monthly, yearly, weekly, etc., preferably using an optional controlled vocabulary in the IntendedFrequency element. Date of first collection should be provided in StartDate as a basis for defining periodicity. EndDate should be entered for data collection cycles with a known or anticipated end date. EndDate is omitted in data collection series that are intended to be on-going.", json_schema_extra={"cogs_name": "DataCollectionFrequency", "description": "Documents the intended frequency of data collection, for example monthly, yearly, weekly, etc., preferably using an optional controlled vocabulary in the IntendedFrequency element. Date of first collection should be provided in StartDate as a basis for defining periodicity. EndDate should be entered for data collection cycles with a known or anticipated end date. EndDate is omitted in data collection series that are intended to be on-going.", "type_name": "DataCollectionFrequencyType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    mode_of_collection: list[ModeOfCollectionType] = Field(default_factory=list, alias="ModeOfCollection", description="Describes the mode of data collection.", json_schema_extra={"cogs_name": "ModeOfCollection", "description": "Describes the mode of data collection.", "type_name": "ModeOfCollectionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    instrument_reference: list[Instrument] = Field(default_factory=list, alias="InstrumentReference", description="References the instrument or instruments used during the process of collecting data for this collection event period.", json_schema_extra={"cogs_name": "InstrumentReference", "description": "References the instrument or instruments used during the process of collecting data for this collection event period.", "type_name": "Instrument", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    collection_situation: list[CollectionSituationType] = Field(default_factory=list, alias="CollectionSituation", description="Describes the situation in which the data collection event takes place. If a number of collection situation types occurred repeat this element.", json_schema_extra={"cogs_name": "CollectionSituation", "description": "Describes the situation in which the data collection event takes place. If a number of collection situation types occurred repeat this element.", "type_name": "CollectionSituationType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    action_to_minimize_losses: list[ActionToMinimizeLossesType] = Field(default_factory=list, alias="ActionToMinimizeLosses", description="Describes action taken to minimize loss of data from the collection event.", json_schema_extra={"cogs_name": "ActionToMinimizeLosses", "description": "Describes action taken to minimize loss of data from the collection event.", "type_name": "ActionToMinimizeLossesType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    quality_statement_reference: list[QualityStatement] = Field(default_factory=list, alias="QualityStatementReference", description="A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", json_schema_extra={"cogs_name": "QualityStatementReference", "description": "A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", "type_name": "QualityStatement", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
