class Concept(Versionable):
    "Describes a concept per ISO/IEC 11179. In addition to the standard name, label, and description, can identify similar concepts, the concept which this concept is a subclass of, a concept that is used to characterize this concept, and a reference to the Universe associated with this concept. It is the linking of a concept to a specific universe (object) that defines this as a data element concept."
    _cogs_type: ClassVar[str] = "Concept"
    _is_abstract: ClassVar[bool] = False
    concept_name: list[LangString] = Field(default_factory=list, alias="ConceptName", description="A name for the Concept.", json_schema_extra={"cogs_name": "ConceptName", "description": "A name for the Concept.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the Concept.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the Concept.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the Concept.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the Concept.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    similar_concept: list[SimilarConceptType] = Field(default_factory=list, alias="SimilarConcept", description="A reference to a concept expressing a similar idea plus a description of the differences. Used to assist in disambiguation of concepts.", json_schema_extra={"cogs_name": "SimilarConcept", "description": "A reference to a concept expressing a similar idea plus a description of the differences. Used to assist in disambiguation of concepts.", "type_name": "SimilarConceptType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    subclass_of_reference: list[Concept] = Field(default_factory=list, alias="SubclassOfReference", description="Reference to a Concept that is used for qualifying this data element concept. The referenced Concept should have its isCharacteristic attribute set to true.", json_schema_extra={"cogs_name": "SubclassOfReference", "description": "Reference to a Concept that is used for qualifying this data element concept. The referenced Concept should have its isCharacteristic attribute set to true.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    excludes_concept_reference: list[Concept] = Field(default_factory=list, alias="ExcludesConceptReference", description="Reference to a Concept that is used for qualifying what is excluded from the Concept's definition.", json_schema_extra={"cogs_name": "ExcludesConceptReference", "description": "Reference to a Concept that is used for qualifying what is excluded from the Concept's definition.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    includes_concept_reference: list[Concept] = Field(default_factory=list, alias="IncludesConceptReference", description="Reference to a Concept that is used for qualifying this is included in the Concept's definition.", json_schema_extra={"cogs_name": "IncludesConceptReference", "description": "Reference to a Concept that is used for qualifying this is included in the Concept's definition.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    is_characteristic: bool | None = Field(default=None, alias="IsCharacteristic", description="If set to \"true\" this concept is used to describe a characteristic of another concept.", json_schema_extra={"cogs_name": "IsCharacteristic", "description": "If set to \"true\" this concept is used to describe a characteristic of another concept.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    broader_reference: list[Concept] = Field(default_factory=list, alias="BroaderReference", description="Reference to a Concept that is broader in meaning (i.e. more general) than this Concept.", json_schema_extra={"cogs_name": "BroaderReference", "description": "Reference to a Concept that is broader in meaning (i.e. more general) than this Concept.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    narrower_reference: list[Concept] = Field(default_factory=list, alias="NarrowerReference", description="Reference to a Concept that is narrower in meaning (i.e. more specific) than this Concept.", json_schema_extra={"cogs_name": "NarrowerReference", "description": "Reference to a Concept that is narrower in meaning (i.e. more specific) than this Concept.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    related_reference: list[Concept] = Field(default_factory=list, alias="RelatedReference", description="Reference to a Concept that has a associative relationship this Concept.", json_schema_extra={"cogs_name": "RelatedReference", "description": "Reference to a Concept that has a associative relationship this Concept.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

class ConceptGroup(Versionable):
    "Allows for grouping of concepts; groups may have a hierarchical structure. This structure should not be used to model semantic concept hierarchies - for this purpose, use the SubclassOfReference element within Concept."
    _cogs_type: ClassVar[str] = "ConceptGroup"
    _is_abstract: ClassVar[bool] = False
    type_of_concept_group: CodeValueType | None = Field(default=None, alias="TypeOfConceptGroup", description="Specifies the purpose of the ConceptGroup. If conceptual the GroupingConceptReference or GroupingUniverseReference should be used to further define the group. The object allows for specification of the purpose using a brief string or term. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "TypeOfConceptGroup", "description": "Specifies the purpose of the ConceptGroup. If conceptual the GroupingConceptReference or GroupingUniverseReference should be used to further define the group. The object allows for specification of the purpose using a brief string or term. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    concept_group_name: list[LangString] = Field(default_factory=list, alias="ConceptGroupName", description="A name for the ConceptGroup.", json_schema_extra={"cogs_name": "ConceptGroupName", "description": "A name for the ConceptGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the ConceptGroup.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the ConceptGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the ConceptGroup.", json_schema_extra={"cogs_name": "Description", "description": "A description of the ConceptGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    grouping_universe_reference: list[Universe] = Field(default_factory=list, alias="GroupingUniverseReference", description="Reference to the universe statement describing the persons or other objects to which the contents of this group pertain. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", json_schema_extra={"cogs_name": "GroupingUniverseReference", "description": "Reference to the universe statement describing the persons or other objects to which the contents of this group pertain. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    grouping_concept_reference: Concept | None = Field(default=None, alias="GroupingConceptReference", description="Reference to the concept expressed by the objects in this group. Expresses a conceptual basis for grouping the concepts. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", json_schema_extra={"cogs_name": "GroupingConceptReference", "description": "Reference to the concept expressed by the objects in this group. Expresses a conceptual basis for grouping the concepts. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    subject: list[InternationalCodeValueType] = Field(default_factory=list, alias="Subject", description="If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Subject", "description": "If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    keyword: list[InternationalCodeValueType] = Field(default_factory=list, alias="Keyword", description="If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Keyword", "description": "If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    concept_reference: list[Concept] = Field(default_factory=list, alias="ConceptReference", description="Reference to a concept included in the concept group. A concept can be referenced internally, from the concept scheme included in the same conceptual components module, or externally, from another scheme. This element is recursive to allow for the description of hierarchical relationships within the concept group.", json_schema_extra={"cogs_name": "ConceptReference", "description": "Reference to a concept included in the concept group. A concept can be referenced internally, from the concept scheme included in the same conceptual components module, or externally, from another scheme. This element is recursive to allow for the description of hierarchical relationships within the concept group.", "type_name": "Concept", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    concept_group_reference: list[ConceptGroup] = Field(default_factory=list, alias="ConceptGroupReference", description="Reference to a subordinate concept group included in the concept group. A concept group can be referenced internally, from the concept scheme included in the same conceptual components module, or externally, from another scheme. This element is recursive to allow for the description of hierarchical relationships within the concept group.", json_schema_extra={"cogs_name": "ConceptGroupReference", "description": "Reference to a subordinate concept group included in the concept group. A concept group can be referenced internally, from the concept scheme included in the same conceptual components module, or externally, from another scheme. This element is recursive to allow for the description of hierarchical relationships within the concept group.", "type_name": "ConceptGroup", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    is_ordered: bool | None = Field(default=None, alias="IsOrdered", description="If set to \"true\" indicates that the content of the group is ordered.", json_schema_extra={"cogs_name": "IsOrdered", "description": "If set to \"true\" indicates that the content of the group is ordered.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    is_administrative_only: bool | None = Field(default=None, alias="IsAdministrativeOnly", description="Indicates the purpose of a concept group.", json_schema_extra={"cogs_name": "IsAdministrativeOnly", "description": "Indicates the purpose of a concept group.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    is_concept: bool | None = Field(default=None, alias="IsConcept", description="A value of true indicates that there is a concept which defines the group, and which is comprised of the concepts contained in the group. A group can be conceptual in purpose (that is, have a value of \"concept\" for the purpose attribute), but not itself have a defining concept.", json_schema_extra={"cogs_name": "IsConcept", "description": "A value of true indicates that there is a concept which defines the group, and which is comprised of the concepts contained in the group. A group can be conceptual in purpose (that is, have a value of \"concept\" for the purpose attribute), but not itself have a defining concept.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class ConceptualVariable(Versionable):
    "Describes a ConceptualVariable which provides the link between a concept to a specific unit type (object) that defines this as a ConceptualVariable. In addition to the standard name, label, and description, it provides the two primary components of a ConceptualVariable by referencing a concept and its related unit type. Note that the concept referenced may itself contain sub-concepts and/or references to similar concepts. This maps to the GSIM ConceptualVariable and has a basis in the ISO/IEC 11179 RepresentedVariableConcept."
    _cogs_type: ClassVar[str] = "ConceptualVariable"
    _is_abstract: ClassVar[bool] = False
    conceptual_variable_name: list[LangString] = Field(default_factory=list, alias="ConceptualVariableName", description="A name for the ConceptualVariable.", json_schema_extra={"cogs_name": "ConceptualVariableName", "description": "A name for the ConceptualVariable.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the ConceptualVariable.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the ConceptualVariable.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the ConceptualVariable.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the ConceptualVariable.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    concept_reference: Concept | None = Field(default=None, alias="ConceptReference", description="Reference to a Concept that is being linked to a UnitType identified by the UnitTypeReference. TypeOfObject should be set to Concept.", json_schema_extra={"cogs_name": "ConceptReference", "description": "Reference to a Concept that is being linked to a UnitType identified by the UnitTypeReference. TypeOfObject should be set to Concept.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    unit_type_reference: UnitType | None = Field(default=None, alias="UnitTypeReference", description="Reference to a unit type being associated with this conceptual variable. TypeOfObject should be set to UnitType.", json_schema_extra={"cogs_name": "UnitTypeReference", "description": "Reference to a unit type being associated with this conceptual variable. TypeOfObject should be set to UnitType.", "type_name": "UnitType", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    category_scheme_reference: CategoryScheme | None = Field(default=None, alias="CategorySchemeReference", description="Reference to a previously created category scheme that represents the conceptual variable's enumerated conceptual domain.", json_schema_extra={"cogs_name": "CategorySchemeReference", "description": "Reference to a previously created category scheme that represents the conceptual variable's enumerated conceptual domain.", "type_name": "CategoryScheme", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})

class ConceptualVariableGroup(Versionable):
    "Contains a group of ConceptualVariables, which may describe an ordered or hierarchical relationship structure. ConceptualVariables may be grouped for a wide range of reasons including conceptual or universe grouping, usage, subject or keyword relationships, or other grouping reason that will assist in the management of a group of ConceptualVariables. Specifies the purpose of the group, a name, label, and description of the group, its relationship to a specific universe or concept, and lists the members of the group."
