class ConditionalTextType(TextContentType):
    "Text which has a changeable value depending on a stated condition, response to earlier questions, or as input from a set of metrics (pre-supplied data)."
    _cogs_type: ClassVar[str] = "ConditionalTextType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    expression: CommandCodeType | None = Field(default=None, alias="Expression", description="The condition on which the associated text varies expressed by a command code. For example, a command that inserts an age by calculating the difference between today’s date and a previously defined date of birth. Use InParameter and OutParameter of parent class to associate Parameters to Alias values in command code.", json_schema_extra={"cogs_name": "Expression", "description": "The condition on which the associated text varies expressed by a command code. For example, a command that inserts an age by calculating the difference between today’s date and a previously defined date of birth. Use InParameter and OutParameter of parent class to associate Parameters to Alias values in command code.", "type_name": "CommandCodeType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    if_then_else_text: IfThenElseTextType | None = Field(default=None, alias="IfThenElseText", description="The condition on which the associated text varies expressed by an IfThenElse decision tree. For example, If MEMBER = 1, Then = [ConditionalResult singular], ElseIf MEMBER > 1, Then = [ConditionalResult plural].  Use InParameter and OutParameter of parent class to associate Parameters to Alias values in the IfCondition.", json_schema_extra={"cogs_name": "IfThenElseText", "description": "The condition on which the associated text varies expressed by an IfThenElse decision tree. For example, If MEMBER = 1, Then = [ConditionalResult singular], ElseIf MEMBER > 1, Then = [ConditionalResult plural].  Use InParameter and OutParameter of parent class to associate Parameters to Alias values in the IfCondition.", "type_name": "IfThenElseTextType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    source_parameter_reference: ParameterType | None = Field(default=None, alias="SourceParameterReference", description="This allows for the simple insert of a piece of information from another specified parameter. For example, if the text of the item using conditional text included the respondent’s name use SourceParameterReference to reference the InParameter of the question that is bound to the OutParameter of the question: \"What is your name?\"", json_schema_extra={"cogs_name": "SourceParameterReference", "description": "This allows for the simple insert of a piece of information from another specified parameter. For example, if the text of the item using conditional text included the respondent’s name use SourceParameterReference to reference the InParameter of the question that is bound to the OutParameter of the question: \"What is your name?\"", "type_name": "ParameterType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

class ContentDateOffsetType(CodeValueType):
    "Identifies the difference between the date applied to the data as a whole and this specific item such as previous year's income or residence 5 years ago. A value of true for the attribute isNegativeOffset indicates that the offset is the specified number of declared units prior to the date of the data as a whole and false indicates information regarding a future state."
