    description: list[LangString] = Field(default_factory=list, alias="Description", description="Full description of the data collection methodology.", json_schema_extra={"cogs_name": "Description", "description": "Full description of the data collection methodology.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})

