    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the DataRelationship.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the DataRelationship.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    logical_record: list[LogicalRecordType] = Field(default_factory=list, alias="LogicalRecord", description="A logical record is a description of all of the elements (variables or NCubes) related to a single case or analysis unit. Required to link a description of a physical record structure to its logical record.", json_schema_extra={"cogs_name": "LogicalRecord", "description": "A logical record is a description of all of the elements (variables or NCubes) related to a single case or analysis unit. Required to link a description of a physical record structure to its logical record.", "type_name": "LogicalRecordType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    record_relationship: list[RecordRelationshipType] = Field(default_factory=list, alias="RecordRelationship", description="Describes the relationship between records of different types or of the same type within a longitudinal study. Identifies the key and linking value relationships. All relationships are pairwise. Multiple pairwise relationships maybe needed to clarify all record relationships within a logical product or data set.", json_schema_extra={"cogs_name": "RecordRelationship", "description": "Describes the relationship between records of different types or of the same type within a longitudinal study. Identifies the key and linking value relationships. All relationships are pairwise. Multiple pairwise relationships maybe needed to clarify all record relationships within a logical product or data set.", "type_name": "RecordRelationshipType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})

