    label: list[LangString] = Field(default_factory=list, alias="Label", description="A label or labels for the embargo element. Repeat for differences in content due to software or application constraints. Language repetition is handled within the structure of the label.", json_schema_extra={"cogs_name": "Label", "description": "A label or labels for the embargo element. Repeat for differences in content due to software or application constraints. Language repetition is handled within the structure of the label.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="Describe the content and coverage of the embargo.", json_schema_extra={"cogs_name": "Description", "description": "Describe the content and coverage of the embargo.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    date: DateType | None = Field(default=None, alias="Date", description="Provides the end date of the embargo, which may take the form of a date range (complete or open ended). Note SimpleDate should not be used for an Embargo Date as an embargo is for a period of time.", json_schema_extra={"cogs_name": "Date", "description": "Provides the end date of the embargo, which may take the form of a date range (complete or open ended). Note SimpleDate should not be used for an Embargo Date as an embargo is for a period of time.", "type_name": "DateType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
