    authorized_source: list[AuthorizedSourceType] = Field(default_factory=list, alias="AuthorizedSource", description="An identifiable authorization source repeated for each identifying code type. This allows the codes to be used as representations for response domains and value representations by designating a specific set of locations and the code of an authorization source. An authorization source should differentiate between codes derived for different purposes within the same agency.", json_schema_extra={"cogs_name": "AuthorizedSource", "description": "An identifiable authorization source repeated for each identifying code type. This allows the codes to be used as representations for response domains and value representations by designating a specific set of locations and the code of an authorization source. An authorization source should differentiate between codes derived for different purposes within the same agency.", "type_name": "AuthorizedSourceType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
