    coordinate_source: CodeValueType | None = Field(default=None, alias="CoordinateSource", description="The standard coordinate source being used. Supports the use of a controlled vocabulary.", json_schema_extra={"cogs_name": "CoordinateSource", "description": "The standard coordinate source being used. Supports the use of a controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    error_correction: CodeValueType | None = Field(default=None, alias="ErrorCorrection", description="The standard method of error correction being used. Supports the use of a controlled vocabulary.", json_schema_extra={"cogs_name": "ErrorCorrection", "description": "The standard method of error correction being used. Supports the use of a controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    offset: str | None = Field(default=None, alias="Offset", description="A definition of the standard offset used when taking a coordinate reading on the geo-referenced object.", json_schema_extra={"cogs_name": "Offset", "description": "A definition of the standard offset used when taking a coordinate reading on the geo-referenced object.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    georeferenced_object: CodeValueType | None = Field(default=None, alias="GeoreferencedObject", description="The standard object for which the geographic coordinates are being captured. This could be a household, village centroid, etc. Supports the use of a controlled vocabulary.", json_schema_extra={"cogs_name": "GeoreferencedObject", "description": "The standard object for which the geographic coordinates are being captured. This could be a household, village centroid, etc. Supports the use of a controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    address_match_type: CodeValueType | None = Field(default=None, alias="AddressMatchType", description="Use for coordinates obtained through address matching only. Identify the address matching method. Example: street segment match, ZIP code centroid, etc. Supports the use of a controlled vocabulary.", json_schema_extra={"cogs_name": "AddressMatchType", "description": "Use for coordinates obtained through address matching only. Identify the address matching method. Example: street segment match, ZIP code centroid, etc. Supports the use of a controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
