class MeasurementItem(Versionable):
    "Structure a single Measurement which may contain one or more response domains (i.e., a list of valid category responses where if \"Other\" is indicated a text response can be used to specify the intent of \"Other\"). The structure provides detail on the intent of the measurement, they type of capture, the valid response options and the number of allowed responses, references to external aids and instructions, and an estimation of the time needed to respond to the measurement. Note that the MeasurementItem is a reusable format for use in any number of applied uses. Additional materials and information can be added within the MeasurementConstruct which is the applied use of a measurement."
    _cogs_type: ClassVar[str] = "MeasurementItem"
    _is_abstract: ClassVar[bool] = False
    measurement_item_name: list[LangString] = Field(default_factory=list, alias="MeasurementItemName", description="A name for the MeasurementItem.", json_schema_extra={"cogs_name": "MeasurementItemName", "description": "A name for the MeasurementItem.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the MeasurementItem.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the MeasurementItem.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the MeasurementItem.", json_schema_extra={"cogs_name": "Description", "description": "A description of the MeasurementItem.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    in_parameter: list[InParameterType] = Field(default_factory=list, alias="InParameter", description="Provides an identity for input objects required for the MeasurementItem.", json_schema_extra={"cogs_name": "InParameter", "description": "Provides an identity for input objects required for the MeasurementItem.", "type_name": "InParameterType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    out_parameter: list[ParameterType] = Field(default_factory=list, alias="OutParameter", description="Provides an identify for the output objects of the MeasurementItem.", json_schema_extra={"cogs_name": "OutParameter", "description": "Provides an identify for the output objects of the MeasurementItem.", "type_name": "ParameterType", "kind": "object", "many": True, "ordered": True, "allow_subtypes": False})
    binding: list[BindingType] = Field(default_factory=list, alias="Binding", description="A structure used to bind the content of a parameter declared as the source to a parameter declared as the target.", json_schema_extra={"cogs_name": "Binding", "description": "A structure used to bind the content of a parameter declared as the source to a parameter declared as the target.", "type_name": "BindingType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    type_of_measurement_item: list[CodeValueType] = Field(default_factory=list, alias="TypeOfMeasurementItem", description="A brief term defining the type of MeasurementItem. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "TypeOfMeasurementItem", "description": "A brief term defining the type of MeasurementItem. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    measurement_item_intent: list[LangString] = Field(default_factory=list, alias="MeasurementItemIntent", description="The purpose of the MeasurementItem in terms of what it is designed to measure.", json_schema_extra={"cogs_name": "MeasurementItemIntent", "description": "The purpose of the MeasurementItem in terms of what it is designed to measure.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    response_domain: SerializeAsAny[RepresentationType] | None = Field(default=None, alias="ResponseDomain", description="Contains a response domain for the measurement item. Typically used to describe simple response domains (textual, numeric, etc.).", json_schema_extra={"cogs_name": "ResponseDomain", "description": "Contains a response domain for the measurement item. Typically used to describe simple response domains (textual, numeric, etc.).", "type_name": "RepresentationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": True})
    response_domain_reference: SerializeAsAny[ManagedRepresentation] | None = Field(default=None, alias="ResponseDomainReference", description="The inclusion of a response domain by reference (must be supported by a managed representation). An abstract element. May be substituted by any valid object of substitution type ResponseDomainReference.", json_schema_extra={"cogs_name": "ResponseDomainReference", "description": "The inclusion of a response domain by reference (must be supported by a managed representation). An abstract element. May be substituted by any valid object of substitution type ResponseDomainReference.", "type_name": "ManagedRepresentation", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    structured_mixed_response_domain: StructuredMixedResponseDomainType | None = Field(default=None, alias="StructuredMixedResponseDomain", description="Use in cases where the measurement requires the option for multiple response domains.", json_schema_extra={"cogs_name": "StructuredMixedResponseDomain", "description": "Use in cases where the measurement requires the option for multiple response domains.", "type_name": "StructuredMixedResponseDomainType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    response_cardinality: ResponseCardinalityType | None = Field(default=None, alias="ResponseCardinality", description="Allows the designation of the minimum and maximum number of responses allowed for this measurement. Note that each response domain has its own response cardinality.", json_schema_extra={"cogs_name": "ResponseCardinality", "description": "Allows the designation of the minimum and maximum number of responses allowed for this measurement. Note that each response domain has its own response cardinality.", "type_name": "ResponseCardinalityType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    concept_reference: list[Concept] = Field(default_factory=list, alias="ConceptReference", description="A reference to the concept associated with the response to the measurement.", json_schema_extra={"cogs_name": "ConceptReference", "description": "A reference to the concept associated with the response to the measurement.", "type_name": "Concept", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    external_aid: list[ExternalAidType] = Field(default_factory=list, alias="ExternalAid", description="A pointer to an external aid presented by the instrument such as a text card, image, audio, or audiovisual aid. Typically a URN. Use type attribute to describe the type of external aid provided. Example of terms to use would include: imageOnly audioOnly audioVisual multiMedia.", json_schema_extra={"cogs_name": "ExternalAid", "description": "A pointer to an external aid presented by the instrument such as a text card, image, audio, or audiovisual aid. Typically a URN. Use type attribute to describe the type of external aid provided. Example of terms to use would include: imageOnly audioOnly audioVisual multiMedia.", "type_name": "ExternalAidType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    external_interviewer_instruction: list[ExternalInterviewerInstructionType] = Field(default_factory=list, alias="ExternalInterviewerInstruction", description="External reference to an interviewer instruction not expressed as DDI XML using OtherMaterial.", json_schema_extra={"cogs_name": "ExternalInterviewerInstruction", "description": "External reference to an interviewer instruction not expressed as DDI XML using OtherMaterial.", "type_name": "ExternalInterviewerInstructionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    interviewer_instruction_attachment: list[AttachedInstructionType] = Field(default_factory=list, alias="InterviewerInstructionAttachment", description="an interviewer instruction expressed as DDI XML.", json_schema_extra={"cogs_name": "InterviewerInstructionAttachment", "description": "an interviewer instruction expressed as DDI XML.", "type_name": "AttachedInstructionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    represented_variable_reference: list[RepresentedVariable] = Field(default_factory=list, alias="RepresentedVariableReference", description="Reference to the RepresentedVariable that describes the data to be collected by this measurement. The RepresentedVariable contains the broad reusable specification of the Variable, i.e., concept, universe, and value representation. When more than one ResponseDomain exists, one RepresentedVariable should be created for each ResponseDomain in the same order as the corresponding ResponseDomain. TypeOfObject should be set to RepresentedVariable.", json_schema_extra={"cogs_name": "RepresentedVariableReference", "description": "Reference to the RepresentedVariable that describes the data to be collected by this measurement. The RepresentedVariable contains the broad reusable specification of the Variable, i.e., concept, universe, and value representation. When more than one ResponseDomain exists, one RepresentedVariable should be created for each ResponseDomain in the same order as the corresponding ResponseDomain. TypeOfObject should be set to RepresentedVariable.", "type_name": "RepresentedVariable", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    development_results_reference: list[DevelopmentResults] = Field(default_factory=list, alias="DevelopmentResultsReference", description="Reference to the development implementation results which gave rise to this version of the object. TypeOfObject should be DevelopmentResults.", json_schema_extra={"cogs_name": "DevelopmentResultsReference", "description": "Reference to the development implementation results which gave rise to this version of the object. TypeOfObject should be DevelopmentResults.", "type_name": "DevelopmentResults", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    estimated_seconds_response_time: CogsDecimal | None = Field(default=None, alias="EstimatedSecondsResponseTime", description="The estimated amount of time required to perform the measurement expressed in seconds. Decimal values should be used to define fractions of seconds.", json_schema_extra={"cogs_name": "EstimatedSecondsResponseTime", "description": "The estimated amount of time required to perform the measurement expressed in seconds. Decimal values should be used to define fractions of seconds.", "type_name": "decimal", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class Methodology(Versionable):
    "Metadata regarding the methodologies used concerning data collection, determining the timing and repetition patterns for data collection, and sampling procedures. Identifies areas where there were deviations from the planned sampling approach, the software used for data collection, and references to any quality standards or statements regarding the processes surrounding the planning and implementation of data collection."
    _cogs_type: ClassVar[str] = "Methodology"
    _is_abstract: ClassVar[bool] = False
    methodology_name: list[LangString] = Field(default_factory=list, alias="MethodologyName", description="A name for the Methodology.", json_schema_extra={"cogs_name": "MethodologyName", "description": "A name for the Methodology.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the Methodology.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the Methodology.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the Methodology.", json_schema_extra={"cogs_name": "Description", "description": "A description of the Methodology.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    data_collection_methodology: list[DataCollectionMethodologyType] = Field(default_factory=list, alias="DataCollectionMethodology", description="Methodologies pertaining to the overall data collection such as primary or secondary data collection, qualitative or quantitative methods, mixed method approaches, GPS capturing methods, methods for collecting data from hard to reach communities, etc. Repeat this element if multiple methodologies are used. Repeat this element if multiple methodologies are used.", json_schema_extra={"cogs_name": "DataCollectionMethodology", "description": "Methodologies pertaining to the overall data collection such as primary or secondary data collection, qualitative or quantitative methods, mixed method approaches, GPS capturing methods, methods for collecting data from hard to reach communities, etc. Repeat this element if multiple methodologies are used. Repeat this element if multiple methodologies are used.", "type_name": "DataCollectionMethodologyType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    time_method: list[TimeMethodType] = Field(default_factory=list, alias="TimeMethod", description="Describes how time fits into the data collection methodology.", json_schema_extra={"cogs_name": "TimeMethod", "description": "Describes how time fits into the data collection methodology.", "type_name": "TimeMethodType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    weighting_methodology_reference: list[WeightingMethodology] = Field(default_factory=list, alias="WeightingMethodologyReference", description="A basic structure for describing the methodology used for weighting. In addition to a descriptive narrative, the methodology may be classified by a short term or external controlled vocabulary.", json_schema_extra={"cogs_name": "WeightingMethodologyReference", "description": "A basic structure for describing the methodology used for weighting. In addition to a descriptive narrative, the methodology may be classified by a short term or external controlled vocabulary.", "type_name": "WeightingMethodology", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    sampling_procedure: list[SamplingProcedureType] = Field(default_factory=list, alias="SamplingProcedure", description="Describes a sampling procedure. If multiple sampling procedures were used repeat this element for each.", json_schema_extra={"cogs_name": "SamplingProcedure", "description": "Describes a sampling procedure. If multiple sampling procedures were used repeat this element for each.", "type_name": "SamplingProcedureType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    deviation_from_sample_design: list[DeviationFromSampleDesignType] = Field(default_factory=list, alias="DeviationFromSampleDesign", description="Describes any deviations from the planned sample design.", json_schema_extra={"cogs_name": "DeviationFromSampleDesign", "description": "Describes any deviations from the planned sample design.", "type_name": "DeviationFromSampleDesignType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    data_collection_software: list[SoftwareType] = Field(default_factory=list, alias="DataCollectionSoftware", description="Specification of a software package used to instantiate a data collection method.", json_schema_extra={"cogs_name": "DataCollectionSoftware", "description": "Specification of a software package used to instantiate a data collection method.", "type_name": "SoftwareType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    quality_statement_reference: list[QualityStatement] = Field(default_factory=list, alias="QualityStatementReference", description="A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", json_schema_extra={"cogs_name": "QualityStatementReference", "description": "A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", "type_name": "QualityStatement", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

class ModeOfCollectionType(IdentifiableType):
    "Describes the mode of collection, i.e., paper questionnaire, observation, web delivered questionnaire, computer assisted interview, automated data harvesting, etc. In addition to the narrative description allows for the use of a brief term or item from a controlled vocabulary to classify the mode used. If multiple modes are used repeat the element."
    _cogs_type: ClassVar[str] = "ModeOfCollectionType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    type_of_mode_of_collection: CodeValueType | None = Field(default=None, alias="TypeOfModeOfCollection", description="Allows brief identification of the mode used with the option of using a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (ModeOfCollection) to support this element at http://www.ddialliance.org/controlled-vocabularies.", json_schema_extra={"cogs_name": "TypeOfModeOfCollection", "description": "Allows brief identification of the mode used with the option of using a controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (ModeOfCollection) to support this element at http://www.ddialliance.org/controlled-vocabularies.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="Full description of the mode of collection.", json_schema_extra={"cogs_name": "Description", "description": "Full description of the mode of collection.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})

class NCube(Versionable):
    "An NCube is a 1..n dimension structure which relates a set of individual values to each other by defining them within a matrix. The NCube may be the result of aggregations, cross-tabulation, time-series, etc. The NCube is described by its dimensions which are represented by categorical variables (variables with a set number of values of specific definition that can be used to identify a specific cell as part of a matrix address). The resulting cells can contain one or more measures, also defined by variables. In addition to the standard name, label, and description of the NCube, it contains a reference to a universe, defines both the normal source of the data in the cells and unit of analysis, the purpose of creating the structured data, the dimensions and measures, as well as the ability to attached any other attribute (i.e., footnote, cell or region specific note) to a specified area of the NCube. Three attribute serve as informational check values; dimensionCount, cellCount, and isClean."
    _cogs_type: ClassVar[str] = "NCube"
    _is_abstract: ClassVar[bool] = False
    n_cube_name: list[LangString] = Field(default_factory=list, alias="NCubeName", description="A name for the NCube.", json_schema_extra={"cogs_name": "NCubeName", "description": "A name for the NCube.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the NCube.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the NCube.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and structure of the NCube.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and structure of the NCube.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="Reference to the universe statement containing a description of the persons or other elements that this NCube refers to, and to which any analytic results refer. If more than one universe is referenced the universe of the variable is the intersect of the referenced universes.", json_schema_extra={"cogs_name": "UniverseReference", "description": "Reference to the universe statement containing a description of the persons or other elements that this NCube refers to, and to which any analytic results refer. If more than one universe is referenced the universe of the variable is the intersect of the referenced universes.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    imputation_reference: SerializeAsAny[ProcessingInstruction] | None = Field(default=None, alias="ImputationReference", description="Reference to an imputation process described as a GeneralInstruction or GenerationInstruction held in a ProcessingInstructionScheme.", json_schema_extra={"cogs_name": "ImputationReference", "description": "Reference to an imputation process described as a GeneralInstruction or GenerationInstruction held in a ProcessingInstructionScheme.", "type_name": "ProcessingInstruction", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    source_unit: CodeValueType | None = Field(default=None, alias="SourceUnit", description="The normal source of the information contained in the NCube. In the case of a survey this may be a respondent, proxy, interviewer, or other source. In the case of administrative data the position of a field on a form e.g., \"top of page\", \"item 3\", \"generated by data processor\", etc. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "SourceUnit", "description": "The normal source of the information contained in the NCube. In the case of a survey this may be a respondent, proxy, interviewer, or other source. In the case of administrative data the position of a field on a form e.g., \"top of page\", \"item 3\", \"generated by data processor\", etc. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    analysis_unit: CodeValueType | None = Field(default=None, alias="AnalysisUnit", description="The entity to which the data refer, for example, individuals, families or households, groups, institutions/organizations, administrative units, etc. Supports the use of an external controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (AnalysisUnit) to support this element at http://www.ddialliance.org/controlled-vocabularies.", json_schema_extra={"cogs_name": "AnalysisUnit", "description": "The entity to which the data refer, for example, individuals, families or households, groups, institutions/organizations, administrative units, etc. Supports the use of an external controlled vocabulary. The DDI Alliance has provided a controlled vocabulary (AnalysisUnit) to support this element at http://www.ddialliance.org/controlled-vocabularies.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    purpose: list[LangString] = Field(default_factory=list, alias="Purpose", description="Purpose for which the NCube was created. For example, designed to support a set of age pyramids generated yearly.", json_schema_extra={"cogs_name": "Purpose", "description": "Purpose for which the NCube was created. For example, designed to support a set of age pyramids generated yearly.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    dimension: list[DimensionType] = Field(default_factory=list, alias="Dimension", description="NCubes are defined by their dimensions. A dimension is provided a rank and a reference to a variable that describes it. Cell locations are \"addressed\" by the value of their intersect on each dimension provided in rank order.", json_schema_extra={"cogs_name": "Dimension", "description": "NCubes are defined by their dimensions. A dimension is provided a rank and a reference to a variable that describes it. Cell locations are \"addressed\" by the value of their intersect on each dimension provided in rank order.", "type_name": "DimensionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    coordinate_region: list[CoordinateRegionType] = Field(default_factory=list, alias="CoordinateRegion", description="Defines the area of attachment for an attribute. It may be defined as the NCube as a whole or as certain dimensions or values of dimensions.", json_schema_extra={"cogs_name": "CoordinateRegion", "description": "Defines the area of attachment for an attribute. It may be defined as the NCube as a whole or as certain dimensions or values of dimensions.", "type_name": "CoordinateRegionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    measure_definition: list[MeasureDefinitionType] = Field(default_factory=list, alias="MeasureDefinition", description="Defines the structure and type of measure captured within the cells. This may be repeated to describe multiple measure for the cells (i.e., count, percent of universe, dimensional percent, index, text, suppression flag, etc.).", json_schema_extra={"cogs_name": "MeasureDefinition", "description": "Defines the structure and type of measure captured within the cells. This may be repeated to describe multiple measure for the cells (i.e., count, percent of universe, dimensional percent, index, text, suppression flag, etc.).", "type_name": "MeasureDefinitionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    attribute: list[AttributeType] = Field(default_factory=list, alias="Attribute", description="An attribute may be any object which should be attached to all or part of the NCube. It may be defined as a Variable or contain textual content (such as a footnote).", json_schema_extra={"cogs_name": "Attribute", "description": "An attribute may be any object which should be attached to all or part of the NCube. It may be defined as a Variable or contain textual content (such as a footnote).", "type_name": "AttributeType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    dimension_count: int | None = Field(default=None, alias="DimensionCount", description="The number of dimensions found in the NCube. Caution in using optional checksums is recommended. Conflict between checksums and the items being counted can cause problems with warning flags during processing. If using checksum to capture information for internal processing purposes, the use of automatically generated check sums is strongly urged.", json_schema_extra={"cogs_name": "DimensionCount", "description": "The number of dimensions found in the NCube. Caution in using optional checksums is recommended. Conflict between checksums and the items being counted can cause problems with warning flags during processing. If using checksum to capture information for internal processing purposes, the use of automatically generated check sums is strongly urged.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    cell_count: int | None = Field(default=None, alias="CellCount", description="The number of cells (measures) found in the NCube. Note that this is the number of cells produced by dimension structure not the number of cells containing data in a sparse NCube. Caution in using optional checksums is recommended. Conflict between checksums and the items being counted can cause problems with warning flags during processing. If using checksum to capture information for internal processing purposes, the use of automatically generated check sums is strongly urged.", json_schema_extra={"cogs_name": "CellCount", "description": "The number of cells (measures) found in the NCube. Note that this is the number of cells produced by dimension structure not the number of cells containing data in a sparse NCube. Caution in using optional checksums is recommended. Conflict between checksums and the items being counted can cause problems with warning flags during processing. If using checksum to capture information for internal processing purposes, the use of automatically generated check sums is strongly urged.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    is_clean: bool | None = Field(default=None, alias="IsClean", description="A value of \"true\" indicates that all cells have the potential for content values. If set to \"false\" Attribute and CoordinateRegion should be used to define the sparse areas of the NCube, those that have no content by definition. For example a cross-tabulation between Household Type (Family, Non-Family) and Number of persons in Household (1,2,3,4,5,6,7+) would need an attribute for Family/1 Person as this will always be empty due to the definition of Family as two or more related persons.", json_schema_extra={"cogs_name": "IsClean", "description": "A value of \"true\" indicates that all cells have the potential for content values. If set to \"false\" Attribute and CoordinateRegion should be used to define the sparse areas of the NCube, those that have no content by definition. For example a cross-tabulation between Household Type (Family, Non-Family) and Number of persons in Household (1,2,3,4,5,6,7+) would need an attribute for Family/1 Person as this will always be empty due to the definition of Family as two or more related persons.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class NCubeGroup(Versionable):
    "Contains a group of NCubes, which may be ordered or hierarchical. In addition to the name, label, and description of the group, the structure allows for defining the type of group using an optional controlled vocabulary, a reference to a defining universe or concept for the group, and a listing of NCubes and NCubeGroups in any order."
    _cogs_type: ClassVar[str] = "NCubeGroup"
    _is_abstract: ClassVar[bool] = False
    type_of_n_cube_group: CodeValueType | None = Field(default=None, alias="TypeOfNCubeGroup", description="A brief textual identification of the group type. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "TypeOfNCubeGroup", "description": "A brief textual identification of the group type. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    n_cube_group_name: list[LangString] = Field(default_factory=list, alias="NCubeGroupName", description="A name for the NCubeGroup.", json_schema_extra={"cogs_name": "NCubeGroupName", "description": "A name for the NCubeGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the NCubeGroup.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the NCubeGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the NCubeGroup.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the NCubeGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="Reference to the universe statement describing the persons or other objects to which the contents of this NCube group pertain.", json_schema_extra={"cogs_name": "UniverseReference", "description": "Reference to the universe statement describing the persons or other objects to which the contents of this NCube group pertain.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    concept_reference: Concept | None = Field(default=None, alias="ConceptReference", description="Reference to the concept expressed by the NCubes in this group.", json_schema_extra={"cogs_name": "ConceptReference", "description": "Reference to the concept expressed by the NCubes in this group.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    subject: list[InternationalCodeValueType] = Field(default_factory=list, alias="Subject", description="If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Subject", "description": "If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    keyword: list[InternationalCodeValueType] = Field(default_factory=list, alias="Keyword", description="If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Keyword", "description": "If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    n_cube_reference: list[NCube] = Field(default_factory=list, alias="NCubeReference", description="Reference to constituent NCube.", json_schema_extra={"cogs_name": "NCubeReference", "description": "Reference to constituent NCube.", "type_name": "NCube", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    n_cube_group_reference: list[NCubeGroup] = Field(default_factory=list, alias="NCubeGroupReference", description="Reference to constituent NCubeGroup. This allows for nesting of NCubeGroups.", json_schema_extra={"cogs_name": "NCubeGroupReference", "description": "Reference to constituent NCubeGroup. This allows for nesting of NCubeGroups.", "type_name": "NCubeGroup", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    is_ordered: bool | None = Field(default=None, alias="IsOrdered", description="If set to \"true\" indicates that the content of the group is ordered.", json_schema_extra={"cogs_name": "IsOrdered", "description": "If set to \"true\" indicates that the content of the group is ordered.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class NCubeInstance(Versionable):
    "A container for defining an instance of an NCube, indicating the matrix address of each cell and where the data for each measure within a cell of the NCube is stored. Allows specifying the values of the attributes attached to a NCube."
    _cogs_type: ClassVar[str] = "NCubeInstance"
    _is_abstract: ClassVar[bool] = False
    n_cube_reference: NCube | None = Field(default=None, alias="NCubeReference", description="Reference to the logical NCube description.", json_schema_extra={"cogs_name": "NCubeReference", "description": "Reference to the logical NCube description.", "type_name": "NCube", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    measure_dimension: MeasureDimensionType | None = Field(default=None, alias="MeasureDimension", description="This element defines the structure of a measure dimension for the NCube Instance. A value along the MeasureDimension is defined by a stack of references to one or more MeasureDefinitions found in the logical description of the NCube with each containing an attribute of orderValue which provides its value for use in the cell address (similar to the use of a CodeRepresentation of a Variable used as a conceptual dimension. This allows measures (whether one or several) to be handled in the same way as the conceptual dimension of the NCube in declaring a cell address. It is assumed that the value of the MeasureDimension is the last value in the address array. For example, for an NCube with 3 conceptual dimensions of rank 1 = Sex, rank 2 = Age, and rank 3 = Educational Attainment, plus a MeasureDimension. The cell address of 1,4,2,2 would indicate Code value of 1 for Sex, 4 for Age, 2 for Educational Attainment, and 2 for MeasureDimension. For systems translating to SDMX or an OLap structure DDI assumes that the MeasureDefinitionReference with the orderValue=\"1\" is the equivalent of the PrimaryMeasure.", json_schema_extra={"cogs_name": "MeasureDimension", "description": "This element defines the structure of a measure dimension for the NCube Instance. A value along the MeasureDimension is defined by a stack of references to one or more MeasureDefinitions found in the logical description of the NCube with each containing an attribute of orderValue which provides its value for use in the cell address (similar to the use of a CodeRepresentation of a Variable used as a conceptual dimension. This allows measures (whether one or several) to be handled in the same way as the conceptual dimension of the NCube in declaring a cell address. It is assumed that the value of the MeasureDimension is the last value in the address array. For example, for an NCube with 3 conceptual dimensions of rank 1 = Sex, rank 2 = Age, and rank 3 = Educational Attainment, plus a MeasureDimension. The cell address of 1,4,2,2 would indicate Code value of 1 for Sex, 4 for Age, 2 for Educational Attainment, and 2 for MeasureDimension. For systems translating to SDMX or an OLap structure DDI assumes that the MeasureDefinitionReference with the orderValue=\"1\" is the equivalent of the PrimaryMeasure.", "type_name": "MeasureDimensionType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    attached_attribute: list[AttachedAttributeType] = Field(default_factory=list, alias="AttachedAttribute", description="This is an attribute attached to the NCube as a whole or a region of the NCube as defined in the logical description as a CoordinateRegion. The content of the attribute can be provided as a single value or reference a location in the data store where the attribute value will be found. This may be in addition to attribute information described in the logical structure.", json_schema_extra={"cogs_name": "AttachedAttribute", "description": "This is an attribute attached to the NCube as a whole or a region of the NCube as defined in the logical description as a CoordinateRegion. The content of the attribute can be provided as a single value or reference a location in the data store where the attribute value will be found. This may be in addition to attribute information described in the logical structure.", "type_name": "AttachedAttributeType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    data_item_n: list[DataItemNType] = Field(default_factory=list, alias="DataItemN", description="Describes a single data item or cell within an NCube Instance. It defines its location within the NCube by its coordinate (matrix) address which is its intersect point on each dimension. Allows for the specification of data item specific attributes, and identifies the physical location of each measure for the data item. May optionally indicate the language of the data contents.", json_schema_extra={"cogs_name": "DataItemN", "description": "Describes a single data item or cell within an NCube Instance. It defines its location within the NCube by its coordinate (matrix) address which is its intersect point on each dimension. Allows for the specification of data item specific attributes, and identifies the physical location of each measure for the data item. May optionally indicate the language of the data contents.", "type_name": "DataItemNType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    default_data_type: CodeValueType | None = Field(default=None, alias="DefaultDataType", description="An explicit definition of the data type that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. This field is necessary in the case of some numeric data formats where the format definition would allow real values, but the values are integer values. Allowed values are: integer (default), real, string.", json_schema_extra={"cogs_name": "DefaultDataType", "description": "An explicit definition of the data type that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. This field is necessary in the case of some numeric data formats where the format definition would allow real values, but the values are integer values. Allowed values are: integer (default), real, string.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    default_delimiter: DelimiterType | None = Field(default=None, alias="DefaultDelimiter", description="Delimiter definition for delimited (free field) data that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: Empty (default), Tab, Blank, AnyString. If a delimiter is used, free field (delimited data) is assumed; binary formats are not allowed.", json_schema_extra={"cogs_name": "DefaultDelimiter", "description": "Delimiter definition for delimited (free field) data that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: Empty (default), Tab, Blank, AnyString. If a delimiter is used, free field (delimited data) is assumed; binary formats are not allowed.", "type_name": "DelimiterType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    default_decimal_positions: int | None = Field(default=None, alias="DefaultDecimalPositions", description="Number of decimal places for data with an implied decimal separator that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Another expression is the decimal scaling factor (SAS). Default: 0.", json_schema_extra={"cogs_name": "DefaultDecimalPositions", "description": "Number of decimal places for data with an implied decimal separator that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Another expression is the decimal scaling factor (SAS). Default: 0.", "type_name": "int", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    default_decimal_separator: str | None = Field(default=None, alias="DefaultDecimalSeparator", description="The character used to separate the integer and the fraction part of a number (if an explicit separator is used in the data) that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: None (default), Dot, Comma, Other. On the basis of the data definition in DDI documents, data processing tools could compute the necessary precision width on the basis of the format width and the existence of separators. Appropriate data types could be used, i.e. float or double, short or long. The decimal separator definition only makes sense with some XML Schema primitives. This is a default which may be overridden in specific cases.", json_schema_extra={"cogs_name": "DefaultDecimalSeparator", "description": "The character used to separate the integer and the fraction part of a number (if an explicit separator is used in the data) that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: None (default), Dot, Comma, Other. On the basis of the data definition in DDI documents, data processing tools could compute the necessary precision width on the basis of the format width and the existence of separators. Appropriate data types could be used, i.e. float or double, short or long. The decimal separator definition only makes sense with some XML Schema primitives. This is a default which may be overridden in specific cases.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    default_digit_group_separator: str | None = Field(default=None, alias="DefaultDigitGroupSeparator", description="The character used to separate groups of digits (if an explicit separator is used in the data) that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: None (default), Dot, Comma, Other. The decimal separator definition makes only sense with some XML Schema primitives. This is a default which may be overridden in specific cases.", json_schema_extra={"cogs_name": "DefaultDigitGroupSeparator", "description": "The character used to separate groups of digits (if an explicit separator is used in the data) that is applied to the majority of the data items reducing the amount of repetitive markup required. It can be overridden at the data item level. Allowed values are: None (default), Dot, Comma, Other. The decimal separator definition makes only sense with some XML Schema primitives. This is a default which may be overridden in specific cases.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    number_of_cases: int | None = Field(default=None, alias="NumberOfCases", description="Total number of cases represented by the contents of the NCube. This is normally the sum of the cell contents when the NCube contains counts and sub-totals are not included.", json_schema_extra={"cogs_name": "NumberOfCases", "description": "Total number of cases represented by the contents of the NCube. This is normally the sum of the cell contents when the NCube contains counts and sub-totals are not included.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

