class NominalRepresentationBaseType(RepresentationType):
    "A means of capturing the features of a nominal (marked/unmarked) response domain. Note that this is not the same as a code or category list with a yes/no set of responses. This representation is generally used in QuestionGrids when defining the response domain of a grid cell. In addition to the basic objects of a representation, the structure defines the allowed content of the mark using a regular expression."
    _cogs_type: ClassVar[str] = "NominalRepresentationBaseType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    reg_exp: str | None = Field(default=None, alias="RegExp", description="The regular expression allows for further description of the allowable content of the data.", json_schema_extra={"cogs_name": "RegExp", "description": "The regular expression allows for further description of the allowable content of the data.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

