    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the OrganizationGroup.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the OrganizationGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="Reference to the universe statement describing the persons or other objects to which the contents of this group pertain.", json_schema_extra={"cogs_name": "UniverseReference", "description": "Reference to the universe statement describing the persons or other objects to which the contents of this group pertain.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
