    organization_reference: list[Organization] = Field(default_factory=list, alias="OrganizationReference", description="Reference to constituent Organization. TypeOfObject should be set to Organization.", json_schema_extra={"cogs_name": "OrganizationReference", "description": "Reference to constituent Organization. TypeOfObject should be set to Organization.", "type_name": "Organization", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    individual_reference: list[Individual] = Field(default_factory=list, alias="IndividualReference", description="Reference to constituent Individual. TypeOfObject should be set to Individual.", json_schema_extra={"cogs_name": "IndividualReference", "description": "Reference to constituent Individual. TypeOfObject should be set to Individual.", "type_name": "Individual", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    relation_reference: list[Relation] = Field(default_factory=list, alias="RelationReference", description="Reference to a constituent Relation. TypeOfObject should be set to Relation.", json_schema_extra={"cogs_name": "RelationReference", "description": "Reference to a constituent Relation. TypeOfObject should be set to Relation.", "type_name": "Relation", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
