    external_urn_reference: str | None = Field(default=None, alias="ExternalURNReference", description="Contains a URN which identifies the cited external resource.", json_schema_extra={"cogs_name": "ExternalURNReference", "description": "Contains a URN which identifies the cited external resource.", "type_name": "anyURI", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
