class ParameterType(IdentifiableType):
    "A parameter is a structure that specifically identifies a source of input or output information so that it can be use pragmatically."
    _cogs_type: ClassVar[str] = "ParameterType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    parameter_name: list[LangString] = Field(default_factory=list, alias="ParameterName", description="A name for the Parameter.", json_schema_extra={"cogs_name": "ParameterName", "description": "A name for the Parameter.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    alias: str | None = Field(default=None, alias="Alias", description="If the content of the parameter is being used in a generic set of code as an alias for the value of an object in a formula (for example source code for a statistical program) enter that name here. This provides a link from the identified parameter to the alias in the code.", json_schema_extra={"cogs_name": "Alias", "description": "If the content of the parameter is being used in a generic set of code as an alias for the value of an object in a formula (for example source code for a statistical program) enter that name here. This provides a link from the identified parameter to the alias in the code.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the Parameter.", json_schema_extra={"cogs_name": "Description", "description": "A description of the Parameter.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    value_representation: SerializeAsAny[RepresentationType] | None = Field(default=None, alias="ValueRepresentation", description="If the content of the parameter contains representational content, such as codes, provide the representation here. ValueRepresentation is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentation. Inclusion of the ValueRepresentation is recommended if you will be sharing data with others as it provides information on the structure of what they can expect to receive when the parameter is processed.", json_schema_extra={"cogs_name": "ValueRepresentation", "description": "If the content of the parameter contains representational content, such as codes, provide the representation here. ValueRepresentation is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentation. Inclusion of the ValueRepresentation is recommended if you will be sharing data with others as it provides information on the structure of what they can expect to receive when the parameter is processed.", "type_name": "RepresentationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": True})
    value_representation_reference: SerializeAsAny[ManagedRepresentation] | None = Field(default=None, alias="ValueRepresentationReference", description="Allows for the use of a ManagedRepresentation by reference. ValueRepresentationReference is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentationReference.", json_schema_extra={"cogs_name": "ValueRepresentationReference", "description": "Allows for the use of a ManagedRepresentation by reference. ValueRepresentationReference is the abstract head of a substitution group and may be replaced with any valid substitution for ValueRepresentationReference.", "type_name": "ManagedRepresentation", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    default_value: ValueType | None = Field(default=None, alias="DefaultValue", description="Provides a default value for the parameter if there is no value provided by the object it is bound to or the process that was intended to produce a value.", json_schema_extra={"cogs_name": "DefaultValue", "description": "Provides a default value for the parameter if there is no value provided by the object it is bound to or the process that was intended to produce a value.", "type_name": "ValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    is_array: bool | None = Field(default=None, alias="IsArray", description="If set to \"true\" indicates that the content of the parameter is a delimited array rather than a single object and should be processed as such.", json_schema_extra={"cogs_name": "IsArray", "description": "If set to \"true\" indicates that the content of the parameter is a delimited array rather than a single object and should be processed as such.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class PhysicalRecordSegmentType(IdentifiableType):
    "A description of the physical record segment as found in the data store. A logical record may be stored in one or more segments housed hierarchically in a single file or in separate data files. All logical records have at least one segment. Identifies the Key variable identifying the segment if the identifier exists in the record, a file name identifier if the segment identification is expressed as part of the file name (used when each segment is stored in a separate file), the order of this segment in relation to other physical segments as part of the logical record, and a flag indicating whether or not the physical segment contains a key."
    _cogs_type: ClassVar[str] = "PhysicalRecordSegmentType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    key_variable_reference: Variable | None = Field(default=None, alias="KeyVariableReference", description="Reference to the Unique key variable for segment identification.", json_schema_extra={"cogs_name": "KeyVariableReference", "description": "Reference to the Unique key variable for segment identification.", "type_name": "Variable", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    key_variable_value: ValueType | None = Field(default=None, alias="KeyVariableValue", description="Value of the variable for this segment.", json_schema_extra={"cogs_name": "KeyVariableValue", "description": "Value of the variable for this segment.", "type_name": "ValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    file_name_identification: str | None = Field(default=None, alias="FileNameIdentification", description="If the file containing this segment has a standard section of its file name, include it here. For example a segment number. For example, in the files 2000SF10001.csv and 2000SF10002.csv the last 4 digits contain the segment number. There is no standard means of specifying this information in a machine-actionable way. This statement is informational but in some legacy files may be the only location where the segment identification is found.", json_schema_extra={"cogs_name": "FileNameIdentification", "description": "If the file containing this segment has a standard section of its file name, include it here. For example a segment number. For example, in the files 2000SF10001.csv and 2000SF10002.csv the last 4 digits contain the segment number. There is no standard means of specifying this information in a machine-actionable way. This statement is informational but in some legacy files may be the only location where the segment identification is found.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    segment_order: int | None = Field(default=None, alias="SegmentOrder", description="Indicates the position of this physical record segment within the logical record expressed as an integer.", json_schema_extra={"cogs_name": "SegmentOrder", "description": "Indicates the position of this physical record segment within the logical record expressed as an integer.", "type_name": "nonNegativeInteger", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    has_segment_key: bool | None = Field(default=None, alias="HasSegmentKey", description="Set to true if there is a variable identifying the segment order. If true a segment key should be declared in a KeyVariableReference. Set to false if there are multiple segments and the identification of a particular segment is based on the order of the records within the file.", json_schema_extra={"cogs_name": "HasSegmentKey", "description": "Set to true if there is a variable identifying the segment order. If true a segment key should be declared in a KeyVariableReference. Set to false if there are multiple segments and the identification of a particular segment is based on the order of the records within the file.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class PhysicalStructure(Versionable):
    "Description of a PhysicalStructure providing the primary link to the LogicalRecord and general structural information. Each description can apply to one or more data files containing the same logical records in the same overall structure."
    _cogs_type: ClassVar[str] = "PhysicalStructure"
    _is_abstract: ClassVar[bool] = False
    physical_structure_name: list[LangString] = Field(default_factory=list, alias="PhysicalStructureName", description="A name for the PhysicalStructure.", json_schema_extra={"cogs_name": "PhysicalStructureName", "description": "A name for the PhysicalStructure.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the PhysicalStructure.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the PhysicalStructure.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
