class SamplingPlan(Versionable):
    "An inline description of a sampling plan (how the sample is drawn). A sampling plan is intended to be versioned over time and can be reused by multiple studies."
    _cogs_type: ClassVar[str] = "SamplingPlan"
    _is_abstract: ClassVar[bool] = False
    type_of_sampling_plan: CodeValueType | None = Field(default=None, alias="TypeOfSamplingPlan", description="A controlled vocabulary covering probability and non-probability sampling methods and modeling approaches. If this is a multi-stage sample the plan at this level should indicate the broadest description of the sampling approaches used in each stage.", json_schema_extra={"cogs_name": "TypeOfSamplingPlan", "description": "A controlled vocabulary covering probability and non-probability sampling methods and modeling approaches. If this is a multi-stage sample the plan at this level should indicate the broadest description of the sampling approaches used in each stage.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    sampling_plan_name: list[LangString] = Field(default_factory=list, alias="SamplingPlanName", description="A name for a sampling plan which may be repeated to express differing names for different systems.", json_schema_extra={"cogs_name": "SamplingPlanName", "description": "A name for a sampling plan which may be repeated to express differing names for different systems.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A full display label for the sampling plan.", json_schema_extra={"cogs_name": "Label", "description": "A full display label for the sampling plan.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="Full description of the sampling plan.", json_schema_extra={"cogs_name": "Description", "description": "Full description of the sampling plan.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    intended_target_population: PopulationType | None = Field(default=None, alias="IntendedTargetPopulation", description="A description of the population that the survey is intended to question (i.e. \"Likely voters\").", json_schema_extra={"cogs_name": "IntendedTargetPopulation", "description": "A description of the population that the survey is intended to question (i.e. \"Likely voters\").", "type_name": "PopulationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    intended_survey_population: PopulationType | None = Field(default=None, alias="IntendedSurveyPopulation", description="The survey population is the set of elements identified by the frame.  For instance, pre-election polls have \"likely voters\" as a target population, but the survey is conducted using RDD (usually).  The survey population is households with active land-line telephones, because that's who we can initially identify.  Survey questions help narrow the respondents into the desired set, but then eliminating sampled units increases variance.  It is reusable in the sense that the same survey population will be used each time the named frame is used.", json_schema_extra={"cogs_name": "IntendedSurveyPopulation", "description": "The survey population is the set of elements identified by the frame.  For instance, pre-election polls have \"likely voters\" as a target population, but the survey is conducted using RDD (usually).  The survey population is households with active land-line telephones, because that's who we can initially identify.  Survey questions help narrow the respondents into the desired set, but then eliminating sampled units increases variance.  It is reusable in the sense that the same survey population will be used each time the named frame is used.", "type_name": "PopulationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    split_rationale: list[LangString] = Field(default_factory=list, alias="SplitRationale", description="Rationale for dividing the frame at this stage into subsets and using a different sampling technique (e.g., Simple Random Sampling or Probability Proportional to Size) on each subset.", json_schema_extra={"cogs_name": "SplitRationale", "description": "Rationale for dividing the frame at this stage into subsets and using a different sampling technique (e.g., Simple Random Sampling or Probability Proportional to Size) on each subset.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    control_construct_reference: SerializeAsAny[ControlConstruct] | None = Field(default=None, alias="ControlConstructReference", description="Generally reference to a single SamplingStage or to a Sequence which orders multiple SamplingStages. TypeOfObject should be any valid member of the group of Control Constructs.", json_schema_extra={"cogs_name": "ControlConstructReference", "description": "Generally reference to a single SamplingStage or to a Sequence which orders multiple SamplingStages. TypeOfObject should be any valid member of the group of Control Constructs.", "type_name": "ControlConstruct", "kind": "item", "many": False, "ordered": False, "allow_subtypes": True})
    stratification_rationale: StratificationRationaleType | None = Field(default=None, alias="StratificationRationale", description="Describe the purpose for stratifying the sampling process.", json_schema_extra={"cogs_name": "StratificationRationale", "description": "Describe the purpose for stratifying the sampling process.", "type_name": "StratificationRationaleType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

class SamplingProcedureType(IdentifiableType):
    "Describes a sampling procedure. If multiple sampling procedures were used repeat this element for each."
