class ScaleRepresentationBaseType(RepresentationType):
    "A means of capturing the structure of Scale for use as a question response domain or variable value representation. In addition to the basic objects of the representation, the structure defines the dimensions of the scale, an intersect for a multi-dimensional scale, and display layout."
    _cogs_type: ClassVar[str] = "ScaleRepresentationBaseType"
    _is_abstract: ClassVar[bool] = False
    _emit_type_field: ClassVar[bool] = True
    scale_dimension: list[ScaleDimensionType] = Field(default_factory=list, alias="ScaleDimension", description="A description of a dimension of the scale. Note that most scales will have only one dimension.", json_schema_extra={"cogs_name": "ScaleDimension", "description": "A description of a dimension of the scale. Note that most scales will have only one dimension.", "type_name": "ScaleDimensionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    dimension_intersect: list[DimensionIntersectType] = Field(default_factory=list, alias="DimensionIntersect", description="Identifies the point at which the scales of a multidimensional scale intersect.", json_schema_extra={"cogs_name": "DimensionIntersect", "description": "Identifies the point at which the scales of a multidimensional scale intersect.", "type_name": "DimensionIntersectType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    display_layout: CodeValueType | None = Field(default=None, alias="DisplayLayout", description="Defines they layout such as containing a drawn scale line, a list of values only, an outline (the boundaries of the area defined by 2 or more intersecting scales such as a diamond of opposites), or some other layout design. Allows for the use of a controlled vocabulary.", json_schema_extra={"cogs_name": "DisplayLayout", "description": "Defines they layout such as containing a drawn scale line, a list of values only, an outline (the boundaries of the area defined by 2 or more intersecting scales such as a diamond of opposites), or some other layout design. Allows for the use of a controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

class StandardWeightType(IdentifiableType):
    "Provides an identified value for a standard weight expressed as an xs:float. This object may be referenced by a variable or statistic and used as a weight for analysis."
