class SubUniverseClass(Versionable):
    "A sub-universe group provides a definition to the universes contained within it. For example the Sub-Universe Group of Gender for the Universe Resident Population may contain the Universe Males and the Universe Females. In addition to the standard name, label, and description, the SubUniverseClass references a concept which defines it, and references to the universes and or other sub-universe groups it contains. The contents of the SubUniverseClass may be designated as ordered."
    _cogs_type: ClassVar[str] = "SubUniverseClass"
    _is_abstract: ClassVar[bool] = False
    sub_universe_class_name: list[LangString] = Field(default_factory=list, alias="SubUniverseClassName", description="A name for the SubUniverseClass.", json_schema_extra={"cogs_name": "SubUniverseClassName", "description": "A name for the SubUniverseClass.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the SubUniverseClass.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the SubUniverseClass.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the SubUniverseClass.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the SubUniverseClass.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    defining_concept_reference: Concept | None = Field(default=None, alias="DefiningConceptReference", description="A concept that provides a grouping factor for the universes contained by the SubUniverseClass. For example if the parent Universe is Population of the World and the two universes in the group are Male and Female the defining concept may be Sex.", json_schema_extra={"cogs_name": "DefiningConceptReference", "description": "A concept that provides a grouping factor for the universes contained by the SubUniverseClass. For example if the parent Universe is Population of the World and the two universes in the group are Male and Female the defining concept may be Sex.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="A reference to a universe contained in this SubUniverseClass. Note that two different parent universes may contain references to the same universe within a sub-universe group. For example, the Universe \"Population of Europe\" and the Universe \"Population of the United States\" may both have a reference to the SubUniverseClass with the defining concept of Gender and member Universes \"Males\" and \"Females\". The SubUniverseClass is ALWAYS a restriction of its parent universe so that in one case it would be \"Males within the Population of Europe\" and in the other usage \"Males within the Population of the United States\". A question or variable should reference each relevant universe to define the appropriate intersect group.", json_schema_extra={"cogs_name": "UniverseReference", "description": "A reference to a universe contained in this SubUniverseClass. Note that two different parent universes may contain references to the same universe within a sub-universe group. For example, the Universe \"Population of Europe\" and the Universe \"Population of the United States\" may both have a reference to the SubUniverseClass with the defining concept of Gender and member Universes \"Males\" and \"Females\". The SubUniverseClass is ALWAYS a restriction of its parent universe so that in one case it would be \"Males within the Population of Europe\" and in the other usage \"Males within the Population of the United States\". A question or variable should reference each relevant universe to define the appropriate intersect group.", "type_name": "Universe", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    sub_universe_class_reference: list[SubUniverseClass] = Field(default_factory=list, alias="SubUniverseClassReference", description="A reference to a SubUniverseClass contained in this SubUniverseClass (a means of nesting hierarchies).", json_schema_extra={"cogs_name": "SubUniverseClassReference", "description": "A reference to a SubUniverseClass contained in this SubUniverseClass (a means of nesting hierarchies).", "type_name": "SubUniverseClass", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
    is_ordered: bool | None = Field(default=None, alias="IsOrdered", description="If set to \"true\" indicates that the content of the group is ordered.", json_schema_extra={"cogs_name": "IsOrdered", "description": "If set to \"true\" indicates that the content of the group is ordered.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

class TemporalCoverageType(IdentifiableType):
    "Describes the temporal coverage of the data described in a particular DDI module. A date may have a subject attached to it if the referent date has limited application."
