    keyword: list[InternationalCodeValueType] = Field(default_factory=list, alias="Keyword", description="If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Keyword", "description": "If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
