    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the UniverseGroup.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the UniverseGroup.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    grouping_universe_reference: list[Universe] = Field(default_factory=list, alias="GroupingUniverseReference", description="Reference to the universe statement describing the persons or other objects to which the contents of this group pertain. This is not a university contained by the group but one that helps define the purpose and application of the group.", json_schema_extra={"cogs_name": "GroupingUniverseReference", "description": "Reference to the universe statement describing the persons or other objects to which the contents of this group pertain. This is not a university contained by the group but one that helps define the purpose and application of the group.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    grouping_concept_reference: Concept | None = Field(default=None, alias="GroupingConceptReference", description="Reference to the concept expressed by the objects in this group. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", json_schema_extra={"cogs_name": "GroupingConceptReference", "description": "Reference to the concept expressed by the objects in this group. Note that this is not a formal linking of a concept to a university such as found in a ConceptualVariable. It is a means of helping to define the context within which this ConceptGroup is relevant.", "type_name": "Concept", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    subject: list[InternationalCodeValueType] = Field(default_factory=list, alias="Subject", description="If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Subject", "description": "If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    keyword: list[InternationalCodeValueType] = Field(default_factory=list, alias="Keyword", description="If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Keyword", "description": "If keywords are listed for this group, it is strongly recommended that the keywords listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of keyword at the group level allows for associating objects as a type of keyword based group or to identify keyword characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="Reference to constituent Universe (from the substitution group). TypeOfObject should be set to Universe.", json_schema_extra={"cogs_name": "UniverseReference", "description": "Reference to constituent Universe (from the substitution group). TypeOfObject should be set to Universe.", "type_name": "Universe", "kind": "item", "many": True, "ordered": True, "allow_subtypes": False})
