    series_context: CodeValueType | None = Field(default=None, alias="SeriesContext", description="A Classification Series can be designed in a specific context. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "SeriesContext", "description": "A Classification Series can be designed in a specific context. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
