    type_of_cognitive_expert_review: CodeValueType | None = Field(default=None, alias="TypeOfCognitiveExpertReview", description="Identifies the specific type of Cognitive Expert Interview. Supports the use of a controlled vocabulary which is strongly recommended.", json_schema_extra={"cogs_name": "TypeOfCognitiveExpertReview", "description": "Identifies the specific type of Cognitive Expert Interview. Supports the use of a controlled vocabulary which is strongly recommended.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

