    geographic_structure_scheme_reference: list[GeographicStructureScheme] = Field(default_factory=list, alias="GeographicStructureSchemeReference", description="Contains a collection of geographic structures.", json_schema_extra={"cogs_name": "GeographicStructureSchemeReference", "description": "Contains a collection of geographic structures.", "type_name": "GeographicStructureScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    geographic_location_scheme_reference: list[GeographicLocationScheme] = Field(default_factory=list, alias="GeographicLocationSchemeReference", description="Contains a collection of geographic locations.", json_schema_extra={"cogs_name": "GeographicLocationSchemeReference", "description": "Contains a collection of geographic locations.", "type_name": "GeographicLocationScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    unit_type_scheme_reference: list[UnitTypeScheme] = Field(default_factory=list, alias="UnitTypeSchemeReference", description="Contains a collection of unit types.", json_schema_extra={"cogs_name": "UnitTypeSchemeReference", "description": "Contains a collection of unit types.", "type_name": "UnitTypeScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

