class DDIInstance(Maintainable):
    "DDIInstance is the top-level publication wrapper for any DDI document. All DDI content published as XML (with the exception of a Fragment intended for transmission) has DDIInstance as its top level structure. In addition to a citation and coverage statement for the instance, the DDIInstance can contain a Group, ResourcePackage, LocalHoldingPackage or StudyUnit. Additional OtherMaterial content may be added but in general OtherMaterial should be listed in the maintainable object containing the objects the OtherMaterial is related to. The instance can provide an applicable DDIProfile either in-line or by reference and can contain overall translation information."
    _cogs_type: ClassVar[str] = "DDIInstance"
    _is_abstract: ClassVar[bool] = False
    citation: CitationType | None = Field(default=None, alias="Citation", description="Citation for the Instance. Note that the citation is optional, because the DDI Instance may contain only reusable component pieces of metadata sets, which are not directly concerned with a single study or studies.", json_schema_extra={"cogs_name": "Citation", "description": "Citation for the Instance. Note that the citation is optional, because the DDI Instance may contain only reusable component pieces of metadata sets, which are not directly concerned with a single study or studies.", "type_name": "CitationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    coverage: CoverageType | None = Field(default=None, alias="Coverage", description="This element contains descriptions of temporal, geographic and topical coverage. At the instance level these descriptions should be inclusive of the coverage of all modules in the instance. The element is available within individual modules and can be used to refine the coverage to that of the individual module.", json_schema_extra={"cogs_name": "Coverage", "description": "This element contains descriptions of temporal, geographic and topical coverage. At the instance level these descriptions should be inclusive of the coverage of all modules in the instance. The element is available within individual modules and can be used to refine the coverage to that of the individual module.", "type_name": "CoverageType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    group_reference: list[Group] = Field(default_factory=list, alias="GroupReference", description="A publication of a Group of StudyUnits in-line.", json_schema_extra={"cogs_name": "GroupReference", "description": "A publication of a Group of StudyUnits in-line.", "type_name": "Group", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    resource_package_reference: list[ResourcePackage] = Field(default_factory=list, alias="ResourcePackageReference", description="A publication of a set of maintainables (modules or schemes) intended for reuse between studies in-line.", json_schema_extra={"cogs_name": "ResourcePackageReference", "description": "A publication of a set of maintainables (modules or schemes) intended for reuse between studies in-line.", "type_name": "ResourcePackage", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    local_holding_package_reference: list[LocalHoldingPackage] = Field(default_factory=list, alias="LocalHoldingPackageReference", description="A publication package containing a deposited publication as well as local value added or processing information in-line.", json_schema_extra={"cogs_name": "LocalHoldingPackageReference", "description": "A publication package containing a deposited publication as well as local value added or processing information in-line.", "type_name": "LocalHoldingPackage", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    study_unit_reference: list[StudyUnit] = Field(default_factory=list, alias="StudyUnitReference", description="A publication of a study unit representing the purpose, background, development, data capture, and data products related to a study in-line.", json_schema_extra={"cogs_name": "StudyUnitReference", "description": "A publication of a study unit representing the purpose, background, development, data capture, and data products related to a study in-line.", "type_name": "StudyUnit", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    ddi_profile_reference: list[DDIProfile] = Field(default_factory=list, alias="DDIProfileReference", description="A DDIProfile applicable to the instance.", json_schema_extra={"cogs_name": "DDIProfileReference", "description": "A DDIProfile applicable to the instance.", "type_name": "DDIProfile", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    translation_information: TranslationType | None = Field(default=None, alias="TranslationInformation", description="TranslationInformation contains information about the translation of the content of the DDI Instance. This includes human-readable information about which language(s) are involved in the translation.", json_schema_extra={"cogs_name": "TranslationInformation", "description": "TranslationInformation contains information about the translation of the content of the DDI Instance. This includes human-readable information about which language(s) are involved in the translation.", "type_name": "TranslationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

class DDIProfile(Maintainable):
    "Describes the subset of valid DDI objects used by an agency for a specified purpose. This may be the required and supported objects for a specific system, a profile for deposit in an archive, requirements at different points of production, etc. In addition to the standard name, label, and description the DDI Profile describes the intended application of the profile, its purpose, the version of XPath used in describing the supported objects, the DDI namespace (major and minor version numbers), a mapping of schema to prefixes (if different from the standard DDI model), a set of instructions for use of the profile, and a listing of used and unsupported objects. These objects may be constrained (i.e., change from optional to required), provided a fixed value, or provided a local name."
    _cogs_type: ClassVar[str] = "DDIProfile"
    _is_abstract: ClassVar[bool] = False
    ddi_profile_name: list[LangString] = Field(default_factory=list, alias="DDIProfileName", description="A name for the profile.", json_schema_extra={"cogs_name": "DDIProfileName", "description": "A name for the profile.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the profile.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the profile.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the profile.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the profile.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    application_of_profile: list[CodeValueType] = Field(default_factory=list, alias="ApplicationOfProfile", description="A brief description of the intended applications of the profile. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "ApplicationOfProfile", "description": "A brief description of the intended applications of the profile. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    purpose: list[LangString] = Field(default_factory=list, alias="Purpose", description="Purpose describes the purpose of creating the profile such as describing the coverage of a distribution software system.", json_schema_extra={"cogs_name": "Purpose", "description": "Purpose describes the purpose of creating the profile such as describing the coverage of a distribution software system.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    x_path_version: CogsDecimal | None = Field(default=None, alias="XPathVersion", description="Provides the version of XPath used. Values are 1.0, 2.0 at this time.", json_schema_extra={"cogs_name": "XPathVersion", "description": "Provides the version of XPath used. Values are 1.0, 2.0 at this time.", "type_name": "decimal", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    ddi_namespace: CogsDecimal | None = Field(default=None, alias="DDINamespace", description="Provides the version of DDI schemas used. Values are 2.5, 3.0, 3.1, etc. Note that only the Major.Minor portion of the version number is used.", json_schema_extra={"cogs_name": "DDINamespace", "description": "Provides the version of DDI schemas used. Values are 2.5, 3.0, 3.1, etc. Note that only the Major.Minor portion of the version number is used.", "type_name": "decimal", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    xml_prefix_map: list[XMLPrefixMapType] = Field(default_factory=list, alias="XMLPrefixMap", description="If you are not using the standard DDI prefix or the full DDI name then provide mapping. For each XML namespace used in the profile's XPath expressions, the XML namespaces must have their prefix specified using this element.", json_schema_extra={"cogs_name": "XMLPrefixMap", "description": "If you are not using the standard DDI prefix or the full DDI name then provide mapping. For each XML namespace used in the profile's XPath expressions, the XML namespaces must have their prefix specified using this element.", "type_name": "XMLPrefixMapType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    instructions: list[LangString] = Field(default_factory=list, alias="Instructions", description="Instructions for use of the profile.", json_schema_extra={"cogs_name": "Instructions", "description": "Instructions for use of the profile.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
