    out_parameter: ParameterType | None = Field(default=None, alias="OutParameter", description="Allows for the response to be bound to one of the QuestionItem's OutParameters, so the collected information can be used elsewhere, for example as inputs to subsequent questions in an Instrument or to a GenerationInstruction. If multiple responses are possible, this would represent and ordered array of the responses.", json_schema_extra={"cogs_name": "OutParameter", "description": "Allows for the response to be bound to one of the QuestionItem's OutParameters, so the collected information can be used elsewhere, for example as inputs to subsequent questions in an Instrument or to a GenerationInstruction. If multiple responses are possible, this would represent and ordered array of the responses.", "type_name": "ParameterType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    response_cardinality: ResponseCardinalityType | None = Field(default=None, alias="ResponseCardinality", description="Allows the designation of the minimum and maximum number of responses allowed for this response domain.", json_schema_extra={"cogs_name": "ResponseCardinality", "description": "Allows the designation of the minimum and maximum number of responses allowed for this response domain.", "type_name": "ResponseCardinalityType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    content_date_offset: ContentDateOffsetType | None = Field(default=None, alias="ContentDateOffset", description="Identifies the difference between the date applied to the data as a whole and this specific item such as previous year's income or residence 5 years ago.", json_schema_extra={"cogs_name": "ContentDateOffset", "description": "Identifies the difference between the date applied to the data as a whole and this specific item such as previous year's income or residence 5 years ago.", "type_name": "ContentDateOffsetType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    display_code: bool | None = Field(default=None, alias="DisplayCode", description="If set to \"true\" (default value) the code value associated with the category label will be displayed. Set to \"false\" if only the category label should not be displayed.", json_schema_extra={"cogs_name": "DisplayCode", "description": "If set to \"true\" (default value) the code value associated with the category label will be displayed. Set to \"false\" if only the category label should not be displayed.", "type_name": "boolean", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

