class IfThenElse(ControlConstruct):
    "A member of the ControlConstruct substitution group. Describes an if-then-else decision type of control construct. IF the stated condition is met, the THEN clause is triggered, otherwise the ELSE clause is triggered. Contains an IfCondition (the condition that must be met to trigger the Then clause), a ThenConstructReference (indicating the construct to invoke if the condition is met), an ElseConstructReference (indicating the construct to invoke if the condition is not met), and an ElseIf structure allowing the expression of multiple conditions to invoke multiple branching."
    _cogs_type: ClassVar[str] = "IfThenElse"
    _is_abstract: ClassVar[bool] = False
    type_of_if_then_else: CodeValueType | None = Field(default=None, alias="TypeOfIfThenElse", description="A brief textual identification of the IfThenElse. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "TypeOfIfThenElse", "description": "A brief textual identification of the IfThenElse. Supports the use of an external controlled vocabulary.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    if_condition: CommandCodeType | None = Field(default=None, alias="IfCondition", description="The condition which must be met to trigger the Then clause, expressed as a CommandCode. The condition is an expression in the programming language used in the instrument.", json_schema_extra={"cogs_name": "IfCondition", "description": "The condition which must be met to trigger the Then clause, expressed as a CommandCode. The condition is an expression in the programming language used in the instrument.", "type_name": "CommandCodeType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    then_construct_reference: Sequence | None = Field(default=None, alias="ThenConstructReference", description="Reference to the control construct which should be triggered if the associated condition is met.", json_schema_extra={"cogs_name": "ThenConstructReference", "description": "Reference to the control construct which should be triggered if the associated condition is met.", "type_name": "Sequence", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    else_if: list[ElseIfType] = Field(default_factory=list, alias="ElseIf", description="Use for multiple branching from a single point in the flow logic represented by the flow logic If, Then, ElseIf, Then, etc.", json_schema_extra={"cogs_name": "ElseIf", "description": "Use for multiple branching from a single point in the flow logic represented by the flow logic If, Then, ElseIf, Then, etc.", "type_name": "ElseIfType", "kind": "object", "many": True, "ordered": True, "allow_subtypes": False})
    else_construct_reference: Sequence | None = Field(default=None, alias="ElseConstructReference", description="Reference to the control construct which is triggered if the associated condition is not met.", json_schema_extra={"cogs_name": "ElseConstructReference", "description": "Reference to the control construct which is triggered if the associated condition is not met.", "type_name": "Sequence", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})

class InLineNCubeRecordLayout(BaseRecordLayout):
    "A member of the BaseRecordLayout substitution group intended for use when the data items of an NCube Instances are captured in-line within the metadata instance. In addition to the link to the PhysicalStructure provided by BaseRecordLayout, the record layout is this namespace (m2) identifies the array base for the in-line data, a full description of each data item contained within an NCube Instance including a link to its description (matrix address) and contained values."
    _cogs_type: ClassVar[str] = "InLineNCubeRecordLayout"
    _is_abstract: ClassVar[bool] = False
    array_base: int | None = Field(default=None, alias="ArrayBase", description="Sets the array base for any arrays used in the definition (that is, whether the first value is in position 0 or 1, etc.). This may be the data array in a delimited data file or the measure array for measures that are bundled and stored in a single location. Array base is generally set to either 0 or 1. There is no override provided as systems processing a record would use a consistent array base.", json_schema_extra={"cogs_name": "ArrayBase", "description": "Sets the array base for any arrays used in the definition (that is, whether the first value is in position 0 or 1, etc.). This may be the data array in a delimited data file or the measure array for measures that are bundled and stored in a single location. Array base is generally set to either 0 or 1. There is no override provided as systems processing a record would use a consistent array base.", "type_name": "int", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})
    n_cube_instance_i_reference: list[NCubeInstanceI] = Field(default_factory=list, alias="NCubeInstanceIReference", description="A container for defining an instance of an NCube, indicating the matrix address of each cell and capturing the data for each measure within a cell of the NCube is stored. Allows specifying the values of the attributes attached to a NCube.", json_schema_extra={"cogs_name": "NCubeInstanceIReference", "description": "A container for defining an instance of an NCube, indicating the matrix address of each cell and capturing the data for each measure within a cell of the NCube is stored. Allows specifying the values of the attributes attached to a NCube.", "type_name": "NCubeInstanceI", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

