class Organization(Agent):
    "Details of an organization including name, contact information, a description, keywords to support searching, their regional affiliation, and any additional information. In addition the organization may capture how they manage version distinction. All agencies should be defined as an Organization and referenced by the Archive module. The organization and specific pieces of information regarding the individual may be tagged for information privacy."
    _cogs_type: ClassVar[str] = "Organization"
    _is_abstract: ClassVar[bool] = False
    organization_identification: OrganizationIdentificationType | None = Field(default=None, alias="OrganizationIdentification", description="Identification information on the Organization. The structure contains a OrganizationName which can be repeated to provide any number of OrganizationNames that have a) a specific contextual usage, or b) are of specific types (e.g. PreviousFormalName). The DDI Maintenance Agency ID and and organization images, such as a building picture or logo are found in OrganizationIdentification. Images and names can be individually date stamped.", json_schema_extra={"cogs_name": "OrganizationIdentification", "description": "Identification information on the Organization. The structure contains a OrganizationName which can be repeated to provide any number of OrganizationNames that have a) a specific contextual usage, or b) are of specific types (e.g. PreviousFormalName). The DDI Maintenance Agency ID and and organization images, such as a building picture or logo are found in OrganizationIdentification. Images and names can be individually date stamped.", "type_name": "OrganizationIdentificationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the organization.", json_schema_extra={"cogs_name": "Description", "description": "A description of the organization.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    keyword: list[InternationalCodeValueType] = Field(default_factory=list, alias="Keyword", description="Keyword used to classify the organization or its activities. Supports the use of an external controlled vocabulary.", json_schema_extra={"cogs_name": "Keyword", "description": "Keyword used to classify the organization or its activities. Supports the use of an external controlled vocabulary.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    regional_coverage: list[CodeValueType] = Field(default_factory=list, alias="RegionalCoverage", description="The geographic region within which this organization operates.", json_schema_extra={"cogs_name": "RegionalCoverage", "description": "The geographic region within which this organization operates.", "type_name": "CodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    additional_information: list[LangString] = Field(default_factory=list, alias="AdditionalInformation", description="Any additional information you which to note about the organization. This is a structured string so it can be formatted and a privacy tag can be applied.", json_schema_extra={"cogs_name": "AdditionalInformation", "description": "Any additional information you which to note about the organization. This is a structured string so it can be formatted and a privacy tag can be applied.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    version_distinction: list[VersionDistinctionType] = Field(default_factory=list, alias="VersionDistinction", description="Describes the data versioning scheme(s) used by an organization. If more than one, Name should differentiate between a standard versioning structure used by the organization and special structures used by specific projects or studies. Information on what drives and major and minor change and how they are structured.", json_schema_extra={"cogs_name": "VersionDistinction", "description": "Describes the data versioning scheme(s) used by an organization. If more than one, Name should differentiate between a standard versioning structure used by the organization and special structures used by specific projects or studies. Information on what drives and major and minor change and how they are structured.", "type_name": "VersionDistinctionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    contact_information: list[ContactInformationType] = Field(default_factory=list, alias="ContactInformation", description="Contact information for the organization including location specification, address, URL, phone numbers, and other means of communication access. Address, location, telephone, and other means of communication can be repeated to express multiple means of a single type or change over time. Each major piece of contact information (with exception of URL contains the element EffectiveDates in order to date stamp the period for which the information is valid.", json_schema_extra={"cogs_name": "ContactInformation", "description": "Contact information for the organization including location specification, address, URL, phone numbers, and other means of communication access. Address, location, telephone, and other means of communication can be repeated to express multiple means of a single type or change over time. Each major piece of contact information (with exception of URL contains the element EffectiveDates in order to date stamp the period for which the information is valid.", "type_name": "ContactInformationType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    privacy: str | None = Field(default=None, alias="Privacy", description="A basic set of privacy codes for the parent element. These may be stricter than the general access restrictions for the overall metadata. If available codes are insufficient this may also contain any string.", json_schema_extra={"cogs_name": "Privacy", "description": "A basic set of privacy codes for the parent element. These may be stricter than the general access restrictions for the overall metadata. If available codes are insufficient this may also contain any string.", "type_name": "string", "kind": "simple", "many": False, "ordered": False, "allow_subtypes": False})

