class PhysicalDataProduct(Maintainable):
    "A module describing the physical storage structures of data files and the relationship of their internal objects to the logical (intellectual) description of the objects found in LogicalProduct. This describes the physical aspects of data files which may be common between one or more data files as described by physical structure of the file and the structure of data items within a record. The PhysicalDataProduct contains the critical links between the physical data store identified by a PhysicalInstance and the logical (intellectual) description of the data as found in the LogicalProduct. In addition to the standard name, label, and description, the module allows for OtherMaterial, and descriptions of PhysicalStructureSchemes and RecordLayoutSchemes in-line or by reference."
    _cogs_type: ClassVar[str] = "PhysicalDataProduct"
    _is_abstract: ClassVar[bool] = False
    physical_data_product_name: list[LangString] = Field(default_factory=list, alias="PhysicalDataProductName", description="A name for the PhysicalDataProduct module.", json_schema_extra={"cogs_name": "PhysicalDataProductName", "description": "A name for the PhysicalDataProduct module.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the PhysicalDataProduct module.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the PhysicalDataProduct module.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the PhysicalDataProduct module.", json_schema_extra={"cogs_name": "Description", "description": "A description of the PhysicalDataProduct module.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    physical_structure_scheme_reference: list[PhysicalStructureScheme] = Field(default_factory=list, alias="PhysicalStructureSchemeReference", description="A scheme containing a set of PhysicalStructures containing descriptions of overall structure of a physical data storage format. These descriptions provide the primary link to the LogicalRecord found in the data file, general structural information such as use of proprietary storage structures, division of logical records into physical segment, and default values for decimal separators, etc. Each description can apply to one or more data files containing the same logical records in the same overall structure.", json_schema_extra={"cogs_name": "PhysicalStructureSchemeReference", "description": "A scheme containing a set of PhysicalStructures containing descriptions of overall structure of a physical data storage format. These descriptions provide the primary link to the LogicalRecord found in the data file, general structural information such as use of proprietary storage structures, division of logical records into physical segment, and default values for decimal separators, etc. Each description can apply to one or more data files containing the same logical records in the same overall structure.", "type_name": "PhysicalStructureScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    record_layout_scheme_reference: list[RecordLayoutScheme] = Field(default_factory=list, alias="RecordLayoutSchemeReference", description="A scheme containing a set of RecordLayouts describing the location of individual data items within the physical record and how to address them (locate and retrieve). RecordLayouts provide a link to the PhysicalStructure description and to individual variables or NCubes describing the data items.", json_schema_extra={"cogs_name": "RecordLayoutSchemeReference", "description": "A scheme containing a set of RecordLayouts describing the location of individual data items within the physical record and how to address them (locate and retrieve). RecordLayouts provide a link to the PhysicalStructure description and to individual variables or NCubes describing the data items.", "type_name": "RecordLayoutScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

class PhysicalInstance(Maintainable):
    "Includes information about the physical instance of a data product (an actual data file). It completes the documentation contained in the Physical Data Product module that is specific to the individual file and serves as a descriptive record of the external data file. Physical Instance provides a citation for the data file, a link to the RecordLayout(s) used by the files records, a description of it coverage (as a constraint if different from the study), check figures for quality control (e.g. digital fingerprint, record count, etc.), and a statistical summary of the data in the file at both the variable and category level."
    _cogs_type: ClassVar[str] = "PhysicalInstance"
    _is_abstract: ClassVar[bool] = False
    citation: CitationType | None = Field(default=None, alias="Citation", description="A citation for the physical instance of a data set. Note that a DOI or similar unique identifier for the data file should be placed in InternationalIdentifier. It is strongly recommended that use of a Citation in this location includes the use of the optional sub-element Title.", json_schema_extra={"cogs_name": "Citation", "description": "A citation for the physical instance of a data set. Note that a DOI or similar unique identifier for the data file should be placed in InternationalIdentifier. It is strongly recommended that use of a Citation in this location includes the use of the optional sub-element Title.", "type_name": "CitationType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    data_fingerprint: list[DataFingerprintType] = Field(default_factory=list, alias="DataFingerprint", description="Allows for assigning a hash value (digital fingerprint) to the data or data file. Set the attribute flag to \"data\" when the hash value provides a digital fingerprint to the data contained in the file regardless of the storage format (ASCII, SAS, binary, etc.). One approach to compute a data fingerprint is the Universal Numerical Fingerprint (UNF). Set the attribute flag to \"dataFile\" if the digital fingerprint is only for the data file in its current storage format.", json_schema_extra={"cogs_name": "DataFingerprint", "description": "Allows for assigning a hash value (digital fingerprint) to the data or data file. Set the attribute flag to \"data\" when the hash value provides a digital fingerprint to the data contained in the file regardless of the storage format (ASCII, SAS, binary, etc.). One approach to compute a data fingerprint is the Universal Numerical Fingerprint (UNF). Set the attribute flag to \"dataFile\" if the digital fingerprint is only for the data file in its current storage format.", "type_name": "DataFingerprintType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    coverage: CoverageType | None = Field(default=None, alias="Coverage", description="Includes information about the topical, spatial, and temporal coverage of the physical instance. May be expressed as a restriction of the parent study coverage.", json_schema_extra={"cogs_name": "Coverage", "description": "Includes information about the topical, spatial, and temporal coverage of the physical instance. May be expressed as a restriction of the parent study coverage.", "type_name": "CoverageType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    data_relationship_reference: list[DataRelationship] = Field(default_factory=list, alias="DataRelationshipReference", description="Reference to the DataRelationship containing the LogicalRecord to which the RecordLayout refers. Repeat for cases where LogicalRecords are described in multiple DataRelationship structures. Note that this does not imply that all of the LogicalRecords described in the DataRelationship are contained, wholly or in part in the PhysicalInstance. This reference allows for a direct path between the PhysicalInstance and the related content found in a LogicalProduct.", json_schema_extra={"cogs_name": "DataRelationshipReference", "description": "Reference to the DataRelationship containing the LogicalRecord to which the RecordLayout refers. Repeat for cases where LogicalRecords are described in multiple DataRelationship structures. Note that this does not imply that all of the LogicalRecords described in the DataRelationship are contained, wholly or in part in the PhysicalInstance. This reference allows for a direct path between the PhysicalInstance and the related content found in a LogicalProduct.", "type_name": "DataRelationship", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    variable_group_reference: list[VariableGroup] = Field(default_factory=list, alias="VariableGroupReference", description="Reference to a grouping of variables that are included in the PhysicalInstance. Variable Groups may represent hierarchical relationships of variables, topical groupings, or administrative groupings.", json_schema_extra={"cogs_name": "VariableGroupReference", "description": "Reference to a grouping of variables that are included in the PhysicalInstance. Variable Groups may represent hierarchical relationships of variables, topical groupings, or administrative groupings.", "type_name": "VariableGroup", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    tabular_n_cube_record_layout_reference: list[TabularNCubeRecordLayout] = Field(default_factory=list, alias="TabularNCubeRecordLayoutReference", description="References the record layout of the data documented in the physical instance.", json_schema_extra={"cogs_name": "TabularNCubeRecordLayoutReference", "description": "References the record layout of the data documented in the physical instance.", "type_name": "TabularNCubeRecordLayout", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    proprietary_record_layout_reference: list[ProprietaryRecordLayout] = Field(default_factory=list, alias="ProprietaryRecordLayoutReference", description="References the record layout of the data documented in the physical instance.", json_schema_extra={"cogs_name": "ProprietaryRecordLayoutReference", "description": "References the record layout of the data documented in the physical instance.", "type_name": "ProprietaryRecordLayout", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    record_layout_reference: list[RecordLayout] = Field(default_factory=list, alias="RecordLayoutReference", description="References the record layout of the data documented in the physical instance.", json_schema_extra={"cogs_name": "RecordLayoutReference", "description": "References the record layout of the data documented in the physical instance.", "type_name": "RecordLayout", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    default_missing_values_reference: ManagedMissingValuesRepresentation | None = Field(default=None, alias="DefaultMissingValuesReference", description="References the content of the default missing values used in the file. The content of this file overrides default missing value information provided in the LogicalRecord. Allows for the specification that is a Systems Missing Value.", json_schema_extra={"cogs_name": "DefaultMissingValuesReference", "description": "References the content of the default missing values used in the file. The content of this file overrides default missing value information provided in the LogicalRecord. Allows for the specification that is a Systems Missing Value.", "type_name": "ManagedMissingValuesRepresentation", "kind": "item", "many": False, "ordered": False, "allow_subtypes": False})
    data_file_identification: list[DataFileIdentificationType] = Field(default_factory=list, alias="DataFileIdentification", description="Identifies the data file documented in the physical instance and provides information about its location.", json_schema_extra={"cogs_name": "DataFileIdentification", "description": "Identifies the data file documented in the physical instance and provides information about its location.", "type_name": "DataFileIdentificationType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    data_file_version: DataFileVersionType | None = Field(default=None, alias="DataFileVersion", description="Provides the version information for the data file related to this physical instance. Note that while Physical Instance allows for multiple copies of the same data file (such as backup copies) the assumption is that they are identical in terms of content, layout, format and version.", json_schema_extra={"cogs_name": "DataFileVersion", "description": "Provides the version information for the data file related to this physical instance. Note that while Physical Instance allows for multiple copies of the same data file (such as backup copies) the assumption is that they are identical in terms of content, layout, format and version.", "type_name": "DataFileVersionType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    information_classification_reference: list[InformationClassification] = Field(default_factory=list, alias="InformationClassificationReference", description="Used to describe the rules and guidelines on how the data is allowed to be handled, transferred, stored and disposed. These confidentiality policies are often dictated by national laws and/or data owners on handling of personal, proprietary, and other sensitive information.", json_schema_extra={"cogs_name": "InformationClassificationReference", "description": "Used to describe the rules and guidelines on how the data is allowed to be handled, transferred, stored and disposed. These confidentiality policies are often dictated by national laws and/or data owners on handling of personal, proprietary, and other sensitive information.", "type_name": "InformationClassification", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    quality_statement_reference: list[QualityStatement] = Field(default_factory=list, alias="QualityStatementReference", description="A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", json_schema_extra={"cogs_name": "QualityStatementReference", "description": "A reference to a Quality Statement pertaining to the quality of the study methodology, metadata, or data to which it is associated. Quality statements may be related to external quality standards.", "type_name": "QualityStatement", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    gross_file_structure: GrossFileStructureType | None = Field(default=None, alias="GrossFileStructure", description="Includes information about the file structure, as well as other characteristics that are specific to the physical instance.", json_schema_extra={"cogs_name": "GrossFileStructure", "description": "Includes information about the file structure, as well as other characteristics that are specific to the physical instance.", "type_name": "GrossFileStructureType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    proprietary_info: ProprietaryInfoType | None = Field(default=None, alias="ProprietaryInfo", description="Contains information proprietary to the software package which produced the data file. This is expressed as a set of name-value pairs. The value may be taken from a controlled vocabulary.", json_schema_extra={"cogs_name": "ProprietaryInfo", "description": "Contains information proprietary to the software package which produced the data file. This is expressed as a set of name-value pairs. The value may be taken from a controlled vocabulary.", "type_name": "ProprietaryInfoType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    statistical_summary: StatisticalSummaryType | None = Field(default=None, alias="StatisticalSummary", description="Includes variable and category statistics data documented in the physical instance, or a reference to a physical instance where the statistics are described or located in line.", json_schema_extra={"cogs_name": "StatisticalSummary", "description": "Includes variable and category statistics data documented in the physical instance, or a reference to a physical instance where the statistics are described or located in line.", "type_name": "StatisticalSummaryType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})
    byte_order: CodeValueType | None = Field(default=None, alias="ByteOrder", description="Contains a term from a controlled vocabulary indicating the byte ordering.", json_schema_extra={"cogs_name": "ByteOrder", "description": "Contains a term from a controlled vocabulary indicating the byte ordering.", "type_name": "CodeValueType", "kind": "object", "many": False, "ordered": False, "allow_subtypes": False})

