    subject: list[InternationalCodeValueType] = Field(default_factory=list, alias="Subject", description="If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", json_schema_extra={"cogs_name": "Subject", "description": "If subjects are listed for this group, it is strongly recommended that the subjects listed also be found in the TopicalCoverage element for the parent packaging element when this group is included directly or by reference in a module containing a coverage element. Use of subject at the group level allows for associating objects as a type of subject based group or to identify subject characteristics of a reusable group of objects.", "type_name": "InternationalCodeValueType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
