    label: list[LangString] = Field(default_factory=list, alias="Label", description="A display label for the PhysicalStructureScheme.", json_schema_extra={"cogs_name": "Label", "description": "A display label for the PhysicalStructureScheme.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the PhysicalStructureScheme.", json_schema_extra={"cogs_name": "Description", "description": "A description of the PhysicalStructureScheme.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    physical_structure_scheme_reference: list[PhysicalStructureScheme] = Field(default_factory=list, alias="PhysicalStructureSchemeReference", description="Reference to an existing PhysicalStructureScheme for inclusion.", json_schema_extra={"cogs_name": "PhysicalStructureSchemeReference", "description": "Reference to an existing PhysicalStructureScheme for inclusion.", "type_name": "PhysicalStructureScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    physical_structure_reference: list[PhysicalStructure] = Field(default_factory=list, alias="PhysicalStructureReference", description="A PhysicalStructure description providing the primary link to the LogicalRecord and general structural information. Each description can apply to one or more data files containing the same logical records in the same overall structure.", json_schema_extra={"cogs_name": "PhysicalStructureReference", "description": "A PhysicalStructure description providing the primary link to the LogicalRecord and general structural information. Each description can apply to one or more data files containing the same logical records in the same overall structure.", "type_name": "PhysicalStructure", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    physical_structure_group_reference: list[PhysicalStructureGroup] = Field(default_factory=list, alias="PhysicalStructureGroupReference", description="A group of PhysicalStructure descriptions for administrative or conceptual purposes.", json_schema_extra={"cogs_name": "PhysicalStructureGroupReference", "description": "A group of PhysicalStructure descriptions for administrative or conceptual purposes.", "type_name": "PhysicalStructureGroup", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

