    external_aid: list[ExternalAidType] = Field(default_factory=list, alias="ExternalAid", description="A pointer to an external aid presented by the instrument such as a text card, image, audio, or audiovisual aid. Typically a URN. Use type attribute to describe the type of external aid provided. Example of terms to use would include: imageOnly audioOnly audioVisual multiMedia.", json_schema_extra={"cogs_name": "ExternalAid", "description": "A pointer to an external aid presented by the instrument such as a text card, image, audio, or audiovisual aid. Typically a URN. Use type attribute to describe the type of external aid provided. Example of terms to use would include: imageOnly audioOnly audioVisual multiMedia.", "type_name": "ExternalAidType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    external_interviewer_instruction: list[ExternalInterviewerInstructionType] = Field(default_factory=list, alias="ExternalInterviewerInstruction", description="External reference to an interviewer instruction not expressed as DDI XML using OtherMaterial.", json_schema_extra={"cogs_name": "ExternalInterviewerInstruction", "description": "External reference to an interviewer instruction not expressed as DDI XML using OtherMaterial.", "type_name": "ExternalInterviewerInstructionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    interviewer_instruction_attachment: list[AttachedInstructionType] = Field(default_factory=list, alias="InterviewerInstructionAttachment", description="an interviewer instruction expressed as DDI XML.", json_schema_extra={"cogs_name": "InterviewerInstructionAttachment", "description": "an interviewer instruction expressed as DDI XML.", "type_name": "AttachedInstructionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
