    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the QuestionGrid.", json_schema_extra={"cogs_name": "Description", "description": "A description of the QuestionGrid.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
