    out_parameter: list[ParameterType] = Field(default_factory=list, alias="OutParameter", description="Provides an identify for the output objects of the QuestionGrid.", json_schema_extra={"cogs_name": "OutParameter", "description": "Provides an identify for the output objects of the QuestionGrid.", "type_name": "ParameterType", "kind": "object", "many": True, "ordered": True, "allow_subtypes": False})
    binding: list[BindingType] = Field(default_factory=list, alias="Binding", description="A structure used to bind the content of a parameter declared as the source to a parameter declared as the target. For example, binding the OutParameter of one Question to the InParameter of another Question in order to personalize a question text. Care should be taken to bind only reusable information at this level. Binding is also available at the QuestionConstruct to reflect bindings particular to the use of the question in a specific question flow or instrument.", json_schema_extra={"cogs_name": "Binding", "description": "A structure used to bind the content of a parameter declared as the source to a parameter declared as the target. For example, binding the OutParameter of one Question to the InParameter of another Question in order to personalize a question text. Care should be taken to bind only reusable information at this level. Binding is also available at the QuestionConstruct to reflect bindings particular to the use of the question in a specific question flow or instrument.", "type_name": "BindingType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    question_text: list[DynamicTextType] = Field(default_factory=list, alias="QuestionText", description="The text of a question. Supports the use of DynamicText. Note that when using QuestionText, the full QuestionText must be repeated for multi-language versions of the content. Different languages may handle the dynamic portions in different locations and/or with different content. Therefore languages cannot be mixed within a dynamic text except when the full text itself has multiple language sections, for example, a foreign language term in a text. The DisplayText may also be repeated to provide a dynamic and plain text version of the display. This allows for accurate rendering of the QuestionText in a non-dynamic environment like print.", json_schema_extra={"cogs_name": "QuestionText", "description": "The text of a question. Supports the use of DynamicText. Note that when using QuestionText, the full QuestionText must be repeated for multi-language versions of the content. Different languages may handle the dynamic portions in different locations and/or with different content. Therefore languages cannot be mixed within a dynamic text except when the full text itself has multiple language sections, for example, a foreign language term in a text. The DisplayText may also be repeated to provide a dynamic and plain text version of the display. This allows for accurate rendering of the QuestionText in a non-dynamic environment like print.", "type_name": "DynamicTextType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
    question_intent: list[LangString] = Field(default_factory=list, alias="QuestionIntent", description="The purpose of the QuestionGrid in terms of what it is designed to test. May contain information on specific aspects of the Grid and its construction.", json_schema_extra={"cogs_name": "QuestionIntent", "description": "The purpose of the QuestionGrid in terms of what it is designed to test. May contain information on specific aspects of the Grid and its construction.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    grid_dimension: list[GridDimensionType] = Field(default_factory=list, alias="GridDimension", description="Describes each dimension of the grid including dimension rank (for the purpose of identifying a cell address), a text for the dimension, and optional labels and codes used as column and row stubs. May also describe a roster (a set of unlabeled rows or columns depending upon display situation).", json_schema_extra={"cogs_name": "GridDimension", "description": "Describes each dimension of the grid including dimension rank (for the purpose of identifying a cell address), a text for the dimension, and optional labels and codes used as column and row stubs. May also describe a roster (a set of unlabeled rows or columns depending upon display situation).", "type_name": "GridDimensionType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
