    _is_abstract: ClassVar[bool] = False
    unit_type_scheme_name: list[LangString] = Field(default_factory=list, alias="UnitTypeSchemeName", description="A name for the scheme.", json_schema_extra={"cogs_name": "UnitTypeSchemeName", "description": "A name for the scheme.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
