    description: list[LangString] = Field(default_factory=list, alias="Description", description="A description of the content and purpose of the UniverseScheme.", json_schema_extra={"cogs_name": "Description", "description": "A description of the content and purpose of the UniverseScheme.", "type_name": "langString", "kind": "simple", "many": True, "ordered": False, "allow_subtypes": False})
    universe_scheme_reference: list[UniverseScheme] = Field(default_factory=list, alias="UniverseSchemeReference", description="Allows the inclusion of a UniverseScheme by reference.", json_schema_extra={"cogs_name": "UniverseSchemeReference", "description": "Allows the inclusion of a UniverseScheme by reference.", "type_name": "UniverseScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    universe_reference: list[Universe] = Field(default_factory=list, alias="UniverseReference", description="Describes a universe (population, object). A universe may be organized into hierarchical sub-universe classes.", json_schema_extra={"cogs_name": "UniverseReference", "description": "Describes a universe (population, object). A universe may be organized into hierarchical sub-universe classes.", "type_name": "Universe", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    universe_group_reference: list[UniverseGroup] = Field(default_factory=list, alias="UniverseGroupReference", description="Describes a group of universes (populations, objects) for administrative purposes.", json_schema_extra={"cogs_name": "UniverseGroupReference", "description": "Describes a group of universes (populations, objects) for administrative purposes.", "type_name": "UniverseGroup", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

