class GeneralInstruction(ProcessingInstruction):
    "Processing instructions that pertain to data collection or data processing overall such as handling of non-response to questions, imputation practices, suppression rules, etc. General instructions should be listed separately to allow for referencing of specific processes."
    _cogs_type: ClassVar[str] = "GeneralInstruction"
    _is_abstract: ClassVar[bool] = False
    command_code: list[CommandCodeType] = Field(default_factory=list, alias="CommandCode", description="Structured information used by a system to process the instruction.", json_schema_extra={"cogs_name": "CommandCode", "description": "Structured information used by a system to process the instruction.", "type_name": "CommandCodeType", "kind": "object", "many": True, "ordered": False, "allow_subtypes": False})
