class LogicalProduct(BaseLogicalProduct):
    "A module describing the logical (intellectual) contents of the quantitative data. It is a member of the substitution group BaseLogicalProduct and contains all of the common features of the BaseLogicalProduct as well as content specific to quantitative data. This is a member of the BaseLogicalProduct substitution group and in addition to the content inherited from the BaseLogicalProduct, contains CategorySchemes, CodeListSchemes, ManagedRepresentationSchemes, RepresentedVariableSchemes, VariableSchemes an NCubeSchemes both in-line an by reference."
    _cogs_type: ClassVar[str] = "LogicalProduct"
    _is_abstract: ClassVar[bool] = False
    category_scheme_reference: list[CategoryScheme] = Field(default_factory=list, alias="CategorySchemeReference", description="Contains descriptions of particular categories used as question responses and in the logical product. Their relationships and code values are described in the code scheme.", json_schema_extra={"cogs_name": "CategorySchemeReference", "description": "Contains descriptions of particular categories used as question responses and in the logical product. Their relationships and code values are described in the code scheme.", "type_name": "CategoryScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    code_list_scheme_reference: list[CodeListScheme] = Field(default_factory=list, alias="CodeListSchemeReference", description="Lists the code values used to represent categories for a variable or question. Also describes hierarchical relationships between categories used in the code scheme.", json_schema_extra={"cogs_name": "CodeListSchemeReference", "description": "Lists the code values used to represent categories for a variable or question. Also describes hierarchical relationships between categories used in the code scheme.", "type_name": "CodeListScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    managed_representation_scheme_reference: list[ManagedRepresentationScheme] = Field(default_factory=list, alias="ManagedRepresentationSchemeReference", description="A scheme containing representations that are being managed as reusable sources for response domains and value representations.", json_schema_extra={"cogs_name": "ManagedRepresentationSchemeReference", "description": "A scheme containing representations that are being managed as reusable sources for response domains and value representations.", "type_name": "ManagedRepresentationScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    represented_variable_scheme_reference: list[RepresentedVariableScheme] = Field(default_factory=list, alias="RepresentedVariableSchemeReference", description="A set of RepresentedVariables managed by an agency. RepresentedVariables are the core reusable parts of a Variable. RepresentedVariable maps to the GSIM Represented Variable. In addition to the standard name, label, and description, allows for the inclusion of an existing RepresentedVariableScheme by reference and RepresentedVariables either in-line or by reference. RepresentedVariables may be grouped for management purposes.", json_schema_extra={"cogs_name": "RepresentedVariableSchemeReference", "description": "A set of RepresentedVariables managed by an agency. RepresentedVariables are the core reusable parts of a Variable. RepresentedVariable maps to the GSIM Represented Variable. In addition to the standard name, label, and description, allows for the inclusion of an existing RepresentedVariableScheme by reference and RepresentedVariables either in-line or by reference. RepresentedVariables may be grouped for management purposes.", "type_name": "RepresentedVariableScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    variable_scheme_reference: list[VariableScheme] = Field(default_factory=list, alias="VariableSchemeReference", description="Contains a collection of variables and variable groups.", json_schema_extra={"cogs_name": "VariableSchemeReference", "description": "Contains a collection of variables and variable groups.", "type_name": "VariableScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})
    n_cube_scheme_reference: list[NCubeScheme] = Field(default_factory=list, alias="NCubeSchemeReference", description="Contains a collection of NCubes and NCube groups.", json_schema_extra={"cogs_name": "NCubeSchemeReference", "description": "Contains a collection of NCubes and NCube groups.", "type_name": "NCubeScheme", "kind": "item", "many": True, "ordered": False, "allow_subtypes": False})

